<file path="src/features/logistics/EmpireEmporiumModal.tsx">
import React, { useState } from 'react';
import type { EmporiumItem } from '../../types/game';
import { X, Store, Coins, Sparkles, ShieldAlert, CheckCircle2, Flame, Users, Shield, Castle, TrendingUp, Snowflake } from 'lucide-react';

interface Props {
  emporiumItems: EmporiumItem[];
  gold: number;
  faith: number;
  purchasedItemIds: string[];
  onClose: () => void;
  onBuyShopItem: (itemId: string) => void;
}

export const EmpireEmporiumModal: React.FC<Props> = ({
  emporiumItems,
  gold,
  faith,
  purchasedItemIds,
  onClose,
  onBuyShopItem,
}) => {
  const [activeTab, setActiveTab] = useState<'decree' | 'perk' | 'spell'>('decree');

  const filteredItems = emporiumItems.filter(item => item.category === activeTab);

  const renderIcon = (iconName: string) => {
    switch (iconName) {
      case 'Users': return <Users className="w-5 h-5 text-amber-400" />;
      case 'Shield': return <Shield className="w-5 h-5 text-cyan-400" />;
      case 'Coins': return <Coins className="w-5 h-5 text-yellow-400" />;
      case 'Castle': return <Castle className="w-5 h-5 text-indigo-400" />;
      case 'TrendingUp': return <TrendingUp className="w-5 h-5 text-green-400" />;
      case 'Sparkles': return <Sparkles className="w-5 h-5 text-purple-400" />;
      case 'Flame': return <Flame className="w-5 h-5 text-red-400" />;
      case 'ShieldAlert': return <ShieldAlert className="w-5 h-5 text-amber-300" />;
      case 'Snowflake': return <Snowflake className="w-5 h-5 text-blue-300" />;
      default: return <Store className="w-5 h-5 text-amber-400" />;
    }
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-50 flex items-center justify-center p-4 sm:p-6 select-none">
      <div className="bg-slate-900 border border-slate-700 rounded-2xl max-w-4xl w-full p-6 relative shadow-2xl flex flex-col max-h-[85vh]">
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 rounded-full transition-colors"
        >
          <X className="w-5 h-5" />
        </button>

        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 pb-4 border-b border-slate-800">
          <div>
            <h2 className="text-2xl font-bold font-serif text-white flex items-center gap-2">
              <Store className="w-6 h-6 text-amber-400" /> Empire Emporium & Grand Sanctuary
            </h2>
            <p className="text-slate-400 text-sm">
              Enact imperial decrees, empower your army with global perks, and unlock holy battle spells.
            </p>
          </div>

          <div className="flex items-center gap-4 bg-slate-950 px-4 py-2 rounded-xl border border-slate-800 self-start sm:self-auto">
            <div className="flex items-center gap-1.5 font-bold text-yellow-400 text-sm">
              <Coins className="w-4 h-4" /> {gold} Gold
            </div>
            <div className="h-4 w-px bg-slate-800" />
            <div className="flex items-center gap-1.5 font-bold text-cyan-400 text-sm">
              <Sparkles className="w-4 h-4" /> {faith} Faith
            </div>
          </div>
        </div>

        {/* Shop Category Tabs */}
        <div className="flex border-b border-slate-800 mb-6 gap-2">
          <button
            onClick={() => setActiveTab('decree')}
            className={`px-5 py-2.5 font-bold text-sm rounded-t-xl transition-all border-b-2 ${
              activeTab === 'decree'
                ? 'border-amber-500 text-amber-400 bg-slate-800/60'
                : 'border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/30'
            }`}
          >
            Emergency Decrees
          </button>

          <button
            onClick={() => setActiveTab('perk')}
            className={`px-5 py-2.5 font-bold text-sm rounded-t-xl transition-all border-b-2 ${
              activeTab === 'perk'
                ? 'border-amber-500 text-amber-400 bg-slate-800/60'
                : 'border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/30'
            }`}
          >
            Global Perks
          </button>

          <button
            onClick={() => setActiveTab('spell')}
            className={`px-5 py-2.5 font-bold text-sm rounded-t-xl transition-all border-b-2 ${
              activeTab === 'spell'
                ? 'border-amber-500 text-amber-400 bg-slate-800/60'
                : 'border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/30'
            }`}
          >
            Battle Spells
          </button>
        </div>

        {/* Tab Items Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 flex-1 overflow-y-auto pr-1">
          {filteredItems.map(item => {
            const isPurchased = item.purchased || purchasedItemIds.includes(item.id);
            const canAfford =
              item.costType === 'gold' ? gold >= item.cost : faith >= item.cost;

            return (
              <div
                key={item.id}
                className={`p-4 rounded-xl border flex flex-col justify-between transition-all ${
                  isPurchased
                    ? 'bg-slate-950/60 border-slate-800 opacity-75'
                    : 'bg-slate-950 border-slate-800 hover:border-slate-700'
                }`}
              >
                <div>
                  <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center gap-2.5">
                      <div className="p-2 bg-slate-900 rounded-lg border border-slate-800">
                        {renderIcon(item.icon)}
                      </div>
                      <div>
                        <h4 className="font-bold text-white text-base">{item.name}</h4>
                        <span className="text-[10px] uppercase font-bold tracking-wider px-2 py-0.5 rounded bg-slate-900 text-slate-400 border border-slate-800">
                          {item.category}
                        </span>
                      </div>
                    </div>

                    {isPurchased && (
                      <span className="flex items-center gap-1 text-xs font-bold text-green-400 bg-green-950/60 px-2 py-0.5 rounded border border-green-800">
                        <CheckCircle2 className="w-3.5 h-3.5" /> Unlocked
                      </span>
                    )}
                  </div>

                  <p className="text-xs text-slate-400 my-3 leading-relaxed">
                    {item.description}
                  </p>
                </div>

                <div className="pt-3 border-t border-slate-800/80 flex justify-between items-center">
                  <div className="text-xs font-bold font-mono">
                    <span className="text-slate-400">Cost: </span>
                    <span
                      className={
                        item.costType === 'gold' ? 'text-yellow-400' : 'text-cyan-400'
                      }
                    >
                      {item.cost} {item.costType === 'gold' ? 'Gold' : 'Faith'}
                    </span>
                  </div>

                  {!isPurchased ? (
                    <button
                      onClick={() => onBuyShopItem(item.id)}
                      disabled={!canAfford}
                      className={`px-4 py-1.5 rounded-lg font-bold text-xs transition-all ${
                        canAfford
                          ? 'bg-amber-600 hover:bg-amber-500 text-black shadow-md'
                          : 'bg-slate-800 text-slate-500 cursor-not-allowed'
                      }`}
                    >
                      {item.category === 'decree' ? 'Enact Decree' : 'Unlock'}
                    </button>
                  ) : (
                    <span className="text-xs text-slate-500 italic">Purchased</span>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {/* Footer */}
        <div className="mt-6 flex justify-end">
          <button
            onClick={onClose}
            className="px-8 py-2.5 bg-amber-600 hover:bg-amber-500 text-black font-bold uppercase tracking-wider rounded-lg shadow-lg"
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
};
</file>

<file path="src/features/logistics/EmpireEmporiumPanel.tsx">
import React, { useState } from 'react';
import type { EmporiumItem } from '../../types/game';
import { Store, Coins, Sparkles, ShieldAlert, CheckCircle2, Flame, Users, Shield, Castle, TrendingUp, Snowflake } from 'lucide-react';

interface Props {
  emporiumItems: EmporiumItem[];
  gold: number;
  faith: number;
  purchasedItemIds: string[];
  onBuyShopItem: (itemId: string) => void;
}

export const EmpireEmporiumPanel: React.FC<Props> = ({
  emporiumItems,
  gold,
  faith,
  purchasedItemIds,
  onBuyShopItem,
}) => {
  const [activeTab, setActiveTab] = useState<'decree' | 'perk' | 'spell'>('decree');

  const filteredItems = emporiumItems.filter(item => item.category === activeTab);

  const renderIcon = (iconName: string) => {
    switch (iconName) {
      case 'Users': return <Users className="w-5 h-5 text-amber-400" />;
      case 'Shield': return <Shield className="w-5 h-5 text-cyan-400" />;
      case 'Coins': return <Coins className="w-5 h-5 text-yellow-400" />;
      case 'Castle': return <Castle className="w-5 h-5 text-indigo-400" />;
      case 'TrendingUp': return <TrendingUp className="w-5 h-5 text-green-400" />;
      case 'Sparkles': return <Sparkles className="w-5 h-5 text-purple-400" />;
      case 'Flame': return <Flame className="w-5 h-5 text-red-400" />;
      case 'ShieldAlert': return <ShieldAlert className="w-5 h-5 text-amber-300" />;
      case 'Snowflake': return <Snowflake className="w-5 h-5 text-blue-300" />;
      default: return <Store className="w-5 h-5 text-amber-400" />;
    }
  };

  return (
    <div className="w-full h-full flex flex-col bg-slate-900 overflow-hidden select-none">
      {/* Header */}
      <div className="p-4 bg-slate-950 border-b border-slate-800">
        <h2 className="text-xl font-bold font-serif text-white flex items-center gap-2">
          <Store className="w-5 h-5 text-amber-400" /> Empire Emporium & Grand Sanctuary
        </h2>
        <p className="text-slate-400 text-xs mt-0.5">
          Enact imperial decrees, empower your army with global perks, and unlock holy battle spells.
        </p>
      </div>

      {/* Category Tabs */}
      <div className="flex border-b border-slate-800 bg-slate-950 px-2 gap-1">
        <button
          onClick={() => setActiveTab('decree')}
          className={`px-4 py-2 font-bold text-xs rounded-t-lg transition-all border-b-2 ${
            activeTab === 'decree'
              ? 'border-amber-500 text-amber-400 bg-slate-900'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          Emergency Decrees
        </button>

        <button
          onClick={() => setActiveTab('perk')}
          className={`px-4 py-2 font-bold text-xs rounded-t-lg transition-all border-b-2 ${
            activeTab === 'perk'
              ? 'border-amber-500 text-amber-400 bg-slate-900'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          Global Perks
        </button>

        <button
          onClick={() => setActiveTab('spell')}
          className={`px-4 py-2 font-bold text-xs rounded-t-lg transition-all border-b-2 ${
            activeTab === 'spell'
              ? 'border-amber-500 text-amber-400 bg-slate-900'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          Battle Spells
        </button>
      </div>

      {/* Tab Items List */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {filteredItems.map(item => {
          const isPurchased = item.purchased || purchasedItemIds.includes(item.id);
          const canAfford =
            item.costType === 'gold' ? gold >= item.cost : faith >= item.cost;

          return (
            <div
              key={item.id}
              className={`p-3.5 rounded-xl border flex flex-col justify-between transition-all ${
                isPurchased
                  ? 'bg-slate-950/60 border-slate-800 opacity-75'
                  : 'bg-slate-950 border-slate-800 hover:border-slate-700'
              }`}
            >
              <div>
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2.5">
                    <div className="p-2 bg-slate-900 rounded-lg border border-slate-800">
                      {renderIcon(item.icon)}
                    </div>
                    <div>
                      <h4 className="font-bold text-white text-sm">{item.name}</h4>
                      <span className="text-[10px] uppercase font-bold tracking-wider px-2 py-0.2 rounded bg-slate-900 text-slate-400 border border-slate-800">
                        {item.category}
                      </span>
                    </div>
                  </div>

                  {isPurchased && (
                    <span className="flex items-center gap-1 text-[11px] font-bold text-green-400 bg-green-950/60 px-2 py-0.5 rounded border border-green-800">
                      <CheckCircle2 className="w-3 h-3" /> Unlocked
                    </span>
                  )}
                </div>

                <p className="text-xs text-slate-400 my-2 leading-relaxed">
                  {item.description}
                </p>
              </div>

              <div className="pt-2 border-t border-slate-800/80 flex justify-between items-center mt-1">
                <div className="text-xs font-bold font-mono">
                  <span className="text-slate-400">Cost: </span>
                  <span
                    className={
                      item.costType === 'gold' ? 'text-yellow-400' : 'text-cyan-400'
                    }
                  >
                    {item.cost} {item.costType === 'gold' ? 'Gold' : 'Faith'}
                  </span>
                </div>

                {!isPurchased ? (
                  <button
                    onClick={() => onBuyShopItem(item.id)}
                    disabled={!canAfford}
                    className={`px-3 py-1 rounded font-bold text-xs transition-all ${
                      canAfford
                        ? 'bg-amber-600 hover:bg-amber-500 text-black shadow-md'
                        : 'bg-slate-800 text-slate-500 cursor-not-allowed'
                    }`}
                  >
                    {item.category === 'decree' ? 'Enact Decree' : 'Unlock'}
                  </button>
                ) : (
                  <span className="text-xs text-slate-500 italic">Purchased</span>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};
</file>

<file path="src/features/logistics/EmpireOverviewPanel.tsx">
import React from 'react';
import type { Territory, UnitTemplate } from '../../types/combat';
import type { EmporiumItem } from '../../types/game';
import { Crown, Coins, Users, Shield, Building2, Flame, Sparkles, Store, Skull } from 'lucide-react';

interface Props {
  territories: Territory[];
  globalUnitPool: UnitTemplate[];
  gold: number;
  faith: number;
  doomClock: number;
  emporiumItems: EmporiumItem[];
  purchasedItemIds: string[];
}

export const EmpireOverviewPanel: React.FC<Props> = ({
  territories,
  globalUnitPool,
  gold,
  faith,
  doomClock,
  emporiumItems,
  purchasedItemIds,
}) => {
  const activeTerritories = territories.filter(t => !t.isScorched);
  const scorchedTerritories = territories.filter(t => t.isScorched);
  const frontlineTerritories = territories.filter(t => t.hasActiveBattle && !t.isScorched);

  // Total Gold and Faith yield from all unscorched territories
  const totalGoldYield = activeTerritories.reduce((acc, t) => acc + t.resourceYield, 0);
  const totalFaithYield = activeTerritories.reduce((acc, t) => acc + (t.faithYield ?? 10), 0);

  // Total assigned units across all territories
  const totalAssignedUnits = territories.reduce((acc, t) => acc + t.allocatedDefenders.length, 0);
  const totalArmySize = globalUnitPool.length + totalAssignedUnits;

  // Total buildings constructed across empire
  const totalBuildings = territories.reduce((acc, t) => {
    return acc + (t.buildings?.length ?? 0);
  }, 0);

  const purchasedPerks = emporiumItems.filter(i => purchasedItemIds.includes(i.id));

  return (
    <div className="w-full h-full flex flex-col bg-slate-900 overflow-hidden select-none">
      {/* Header */}
      <div className="p-4 bg-slate-950 border-b border-slate-800 flex items-center justify-between">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="text-xs uppercase font-bold tracking-widest px-2.5 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-800 flex items-center gap-1">
              <Crown className="w-3.5 h-3.5" /> High Imperial Realm
            </span>
          </div>
          <h2 className="text-2xl font-bold font-serif text-white">Empire Strategic Overview</h2>
        </div>
      </div>

      {/* Scrollable Content */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {/* Macro KPI Cards */}
        <div className="grid grid-cols-2 gap-3">
          <div className="bg-slate-950 p-3.5 rounded-xl border border-slate-800">
            <div className="text-xs text-slate-400 font-semibold uppercase flex items-center gap-1">
              <Coins className="w-3.5 h-3.5 text-yellow-400" /> Empire Yields
            </div>
            <div className="text-lg font-bold text-green-400 mt-1">+{totalGoldYield}g Gold / turn</div>
            <div className="text-lg font-bold text-cyan-400 mt-0.5">+{totalFaithYield} Faith / turn</div>
            <div className="text-[11px] text-yellow-400 font-mono mt-1 font-semibold border-t border-slate-800 pt-1">
              Treasury: {gold} Gold • {faith} Faith
            </div>
          </div>

          <div className="bg-slate-950 p-3.5 rounded-xl border border-slate-800">
            <div className="text-xs text-slate-400 font-semibold uppercase flex items-center gap-1">
              <Users className="w-3.5 h-3.5 text-cyan-400" /> Grand Army Size
            </div>
            <div className="text-xl font-bold text-cyan-400 mt-1">{totalArmySize} Units</div>
            <div className="text-[11px] text-slate-500 mt-0.5">
              {globalUnitPool.length} reserve • {totalAssignedUnits} deployed • {doomClock <= 1 ? 'Doomsday is Coming!' : `Doom in: ${doomClock}`}
            </div>
          </div>
        </div>

        {/* Realm Status Summary */}
        <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 space-y-2.5">
          <h3 className="text-xs font-bold uppercase tracking-wider text-slate-300 flex items-center gap-2 border-b border-slate-800 pb-2">
            <Shield className="w-4 h-4 text-amber-400" /> Realm Territorial Status
          </h3>

          <div className="grid grid-cols-3 gap-2 text-center text-xs">
            <div className="bg-slate-900 p-2.5 rounded-lg border border-slate-800">
              <div className="text-slate-400">Controlled</div>
              <div className="text-lg font-bold text-white mt-0.5">{activeTerritories.length} / {territories.length}</div>
            </div>

            <div className="bg-slate-900 p-2.5 rounded-lg border border-slate-800">
              <div className="text-slate-400 flex items-center justify-center gap-1">
                <Flame className="w-3 h-3 text-red-400" /> Frontline
              </div>
              <div className="text-lg font-bold text-red-400 mt-0.5">{frontlineTerritories.length}</div>
            </div>

            <div className="bg-slate-900 p-2.5 rounded-lg border border-slate-800">
              <div className="text-slate-400 flex items-center justify-center gap-1">
                <Skull className="w-3 h-3 text-slate-500" /> Scorched
              </div>
              <div className="text-lg font-bold text-slate-500 mt-0.5">{scorchedTerritories.length}</div>
            </div>
          </div>
        </div>

        {/* Infrastructure & Buildings Overview */}
        <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 space-y-2.5">
          <h3 className="text-xs font-bold uppercase tracking-wider text-slate-300 flex items-center gap-2 border-b border-slate-800 pb-2">
            <Building2 className="w-4 h-4 text-indigo-400" /> Infrastructure Summary
          </h3>
          <div className="flex justify-between items-center text-xs text-slate-300 bg-slate-900 p-3 rounded-lg border border-slate-800">
            <span>Total Constructed Town Buildings:</span>
            <span className="font-bold text-amber-400 font-mono text-sm">{totalBuildings} Buildings</span>
          </div>
        </div>

        {/* Active Perks & Decrees */}
        <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 space-y-2.5">
          <h3 className="text-xs font-bold uppercase tracking-wider text-slate-300 flex items-center gap-2 border-b border-slate-800 pb-2">
            <Store className="w-4 h-4 text-purple-400" /> Active Emporium Blessings ({purchasedPerks.length})
          </h3>

          {purchasedPerks.length === 0 ? (
            <div className="text-slate-500 text-xs italic py-2">No global perks or spells unlocked yet. Visit the Empire Emporium to enact decrees.</div>
          ) : (
            <div className="space-y-1.5">
              {purchasedPerks.map(perk => (
                <div key={perk.id} className="p-2 bg-slate-900 rounded-lg border border-slate-800 text-xs flex justify-between items-center">
                  <span className="font-bold text-white flex items-center gap-1.5">
                    <Sparkles className="w-3 h-3 text-purple-400" /> {perk.name}
                  </span>
                  <span className="text-[10px] uppercase font-bold text-green-400 px-1.5 py-0.2 bg-green-950 rounded border border-green-800">Active</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
</file>

<file path="src/features/logistics/RingMapView.tsx">
import React, { useState, useRef } from 'react';
import type { Territory } from '../../types/combat';
import { Flame, Shield, Skull, Zap, Move, ZoomIn, ZoomOut } from 'lucide-react';

interface Props {
  territories: Territory[];
  selectedTerritoryId: string | null;
  onSelectTerritory: (territoryId: string) => void;
  validTerritoryIds?: string[];
}

export const RingMapView: React.FC<Props> = ({
  territories,
  selectedTerritoryId,
  onSelectTerritory,
  validTerritoryIds,
}) => {
  // Pan & Zoom State
  const [panOffset, setPanOffset] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [zoomScale, setZoomScale] = useState<number>(1.0);
  const MIN_ZOOM = 0.6;
  const MAX_ZOOM = 1.8;

  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const panStartRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const didDragRef = useRef(false);

  const getTerritoryPosition = (territory: Territory, all: Territory[]) => {
    const sameRing = all.filter(t => t.ringLevel === territory.ringLevel);
    const index = sameRing.findIndex(t => t.id === territory.id);
    const count = sameRing.length;

    const ringRadii: Record<number, number> = {
      0: 0,
      1: 110,
      2: 195,
      3: 275,
    };

    const radius = ringRadii[territory.ringLevel] ?? (territory.ringLevel * 90);

    if (territory.ringLevel === 0) {
      return { x: 400, y: 300 };
    }

    const baseAngles: Record<number, number> = {
      1: -90,
      2: 30,
      3: 150,
    };
    const baseAngle = baseAngles[territory.ringLevel] ?? 0;
    const angleStep = 360 / Math.max(1, count);
    const angleDeg = baseAngle + index * angleStep;
    const angleRad = (angleDeg * Math.PI) / 180;

    return {
      x: 400 + radius * Math.cos(angleRad),
      y: 300 + radius * Math.sin(angleRad),
    };
  };

  const center = { x: 400, y: 300 };
  const positions = territories.map(t => ({
    territory: t,
    pos: getTerritoryPosition(t, territories),
  }));

  // Pan Handlers
  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return;
    setIsDragging(true);
    didDragRef.current = false;
    dragStartRef.current = { x: e.clientX, y: e.clientY };
    panStartRef.current = { ...panOffset };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    const dx = e.clientX - dragStartRef.current.x;
    const dy = e.clientY - dragStartRef.current.y;

    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
      didDragRef.current = true;
    }

    const maxPanX = 380;
    const maxPanY = 280;

    setPanOffset({
      x: Math.max(-maxPanX, Math.min(maxPanX, panStartRef.current.x + dx)),
      y: Math.max(-maxPanY, Math.min(maxPanY, panStartRef.current.y + dy)),
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  // Zoom Wheel Handler
  const handleWheel = (e: React.WheelEvent) => {
    const delta = e.deltaY < 0 ? 0.1 : -0.1;
    setZoomScale(prev => Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, parseFloat((prev + delta).toFixed(2)))));
  };

  const handleZoomIn = (e: React.MouseEvent) => {
    e.stopPropagation();
    setZoomScale(prev => Math.min(MAX_ZOOM, parseFloat((prev + 0.15).toFixed(2))));
  };

  const handleZoomOut = (e: React.MouseEvent) => {
    e.stopPropagation();
    setZoomScale(prev => Math.max(MIN_ZOOM, parseFloat((prev - 0.15).toFixed(2))));
  };

  const handleResetView = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPanOffset({ x: 0, y: 0 });
    setZoomScale(1.0);
  };

  const handleNodeClick = (e: React.MouseEvent, territoryId: string) => {
    e.stopPropagation();
    if (!didDragRef.current) {
      onSelectTerritory(territoryId);
    }
  };

  return (
    <div
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      className={`relative w-full h-full min-h-[500px] flex items-center justify-center bg-slate-950 overflow-hidden select-none ${
        isDragging ? 'cursor-grabbing' : 'cursor-grab'
      }`}
    >
      {/* Pan & Zoom Controls */}
      <div className="absolute top-4 left-4 z-10 flex items-center gap-2 bg-slate-900/85 backdrop-blur border border-slate-800 px-3 py-1.5 rounded-lg text-xs text-slate-400 font-sans shadow-md">
        <span className="flex items-center gap-1 text-slate-300 font-semibold mr-2">
          <Move className="w-3.5 h-3.5 text-cyan-400" /> Scroll / Drag Map
        </span>
        <div className="flex items-center gap-1 border-l border-slate-800 pl-2">
          <button
            onClick={handleZoomOut}
            disabled={zoomScale <= MIN_ZOOM}
            className="p-1 hover:bg-slate-800 text-slate-300 disabled:opacity-30 rounded transition-colors"
            title="Zoom Out"
          >
            <ZoomOut className="w-3.5 h-3.5" />
          </button>
          <span className="text-[11px] font-mono font-bold text-amber-400 w-10 text-center">
            {Math.round(zoomScale * 100)}%
          </span>
          <button
            onClick={handleZoomIn}
            disabled={zoomScale >= MAX_ZOOM}
            className="p-1 hover:bg-slate-800 text-slate-300 disabled:opacity-30 rounded transition-colors"
            title="Zoom In"
          >
            <ZoomIn className="w-3.5 h-3.5" />
          </button>
        </div>
        {(panOffset.x !== 0 || panOffset.y !== 0 || zoomScale !== 1.0) && (
          <button
            onClick={handleResetView}
            className="ml-1 px-2 py-0.5 bg-slate-800 hover:bg-slate-700 text-amber-400 rounded text-[11px] font-bold transition-colors"
          >
            Reset
          </button>
        )}
      </div>

      {/* SVG Canvas View */}
      <svg className="w-full h-full max-w-[900px] max-h-[650px]" viewBox="0 0 800 600">
        <defs>
          <radialGradient id="ringBgGrad" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#1e1b4b" stopOpacity="0.4" />
            <stop offset="60%" stopColor="#0f172a" stopOpacity="0.8" />
            <stop offset="100%" stopColor="#020617" stopOpacity="1" />
          </radialGradient>
          <filter id="glow" x="-30%" y="-30%" width="160%" height="160%">
            <feGaussianBlur stdDeviation="4" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Draggable & Scalable Map Wrapper */}
        <g
          transform={`translate(${panOffset.x}, ${panOffset.y}) scale(${zoomScale})`}
          style={{ transformOrigin: '400px 300px' }}
        >
          {/* Ambient Ring Grid Background */}
          <circle cx={center.x} cy={center.y} r="350" fill="url(#ringBgGrad)" />

          {/* Concentric Orbital Rings */}
          <circle cx={center.x} cy={center.y} r="275" stroke="#334155" strokeWidth="1.5" strokeDasharray="6 6" fill="none" />
          <circle cx={center.x} cy={center.y} r="195" stroke="#475569" strokeWidth="1.5" strokeDasharray="4 4" fill="none" />
          <circle cx={center.x} cy={center.y} r="110" stroke="#64748b" strokeWidth="2" fill="none" />

          {/* Outer Ring Radial Spokes */}
          {positions.map(({ territory, pos }) => {
            if (territory.ringLevel === 0) return null;
            return (
              <line
                key={`line-${territory.id}`}
                x1={center.x}
                y1={center.y}
                x2={pos.x}
                y2={pos.y}
                stroke={territory.hasActiveBattle ? "#ef4444" : territory.isScorched ? "#334155" : "#475569"}
                strokeWidth={territory.hasActiveBattle ? "2.5" : "1.5"}
                strokeDasharray={territory.isScorched ? "4 4" : "none"}
                opacity={0.6}
              />
            );
          })}

          {/* Ring Labels */}
          <text x={center.x} y={center.y - 280} fill="#64748b" fontSize="10" fontWeight="bold" textAnchor="middle" letterSpacing="2">
            OUTER RING III
          </text>
          <text x={center.x} y={center.y - 200} fill="#64748b" fontSize="10" fontWeight="bold" textAnchor="middle" letterSpacing="2">
            MIDDLE RING II
          </text>
          <text x={center.x} y={center.y - 115} fill="#64748b" fontSize="10" fontWeight="bold" textAnchor="middle" letterSpacing="2">
            INNER FORTRESS RING I
          </text>

          {/* Interactive Territory Nodes */}
          {positions.map(({ territory, pos }) => {
            const isSelected = territory.id === selectedTerritoryId;
            const isDanger = territory.hasActiveBattle;
            const isScorched = territory.isScorched;
            const isCitadel = territory.ringLevel === 0;
            const isValidTarget = !validTerritoryIds || validTerritoryIds.includes(territory.id);

            const nodeColor = isScorched
              ? "#334155"
              : isDanger
              ? "#ef4444"
              : isCitadel
              ? "#f59e0b"
              : "#06b6d4";

            return (
              <g
                key={territory.id}
                transform={`translate(${pos.x}, ${pos.y})`}
                onClick={(e) => isValidTarget && handleNodeClick(e, territory.id)}
                className={isValidTarget ? "cursor-pointer group" : "opacity-25 grayscale pointer-events-none"}
              >
                {/* Scalable Node Group with perfectly centered origin transform */}
                <g className="transition-transform duration-200 ease-out group-hover:scale-110">
                  {/* Selection Glow Pulse */}
                  {isSelected && (
                    <circle
                      cx={0}
                      cy={0}
                      r={isCitadel ? 42 : 36}
                      fill="none"
                      stroke="#fbbf24"
                      strokeWidth="3"
                      filter="url(#glow)"
                      className="animate-pulse"
                    />
                  )}

                  {/* Danger Pulsing Ring */}
                  {isDanger && !isScorched && (
                    <circle
                      cx={0}
                      cy={0}
                      r={isCitadel ? 46 : 38}
                      fill="none"
                      stroke="#ef4444"
                      strokeWidth="2.5"
                      opacity="0.8"
                      className="animate-ping"
                    />
                  )}

                  {/* Node Base Circle */}
                  <circle
                    cx={0}
                    cy={0}
                    r={isCitadel ? 34 : 28}
                    fill={isScorched ? "#0f172a" : "#1e293b"}
                    stroke={nodeColor}
                    strokeWidth={isSelected ? "4" : "2.5"}
                  />

                  {/* Inner Node Glow */}
                  <circle
                    cx={0}
                    cy={0}
                    r={isCitadel ? 24 : 18}
                    fill={nodeColor}
                    opacity={isScorched ? 0.2 : 0.4}
                  />

                  {/* Center Icon */}
                  <foreignObject
                    x={-14}
                    y={-14}
                    width="28"
                    height="28"
                    className="pointer-events-none"
                  >
                    <div className="w-full h-full flex items-center justify-center text-white">
                      {isScorched ? (
                        <Skull className="w-5 h-5 text-slate-500" />
                      ) : isDanger ? (
                        <Flame className="w-6 h-6 text-red-400 animate-bounce" />
                      ) : isCitadel ? (
                        <Zap className="w-6 h-6 text-amber-300" />
                      ) : (
                        <Shield className="w-5 h-5 text-cyan-300" />
                      )}
                    </div>
                  </foreignObject>

                  {/* Defender Count Badge */}
                  {!isScorched && (
                    <g transform="translate(16, -20)">
                      <rect
                        x="0"
                        y="0"
                        width="24"
                        height="18"
                        rx="9"
                        fill="#0f172a"
                        stroke="#fbbf24"
                        strokeWidth="1.5"
                      />
                      <text
                        x="12"
                        y="13"
                        fill="#fbbf24"
                        fontSize="10"
                        fontWeight="bold"
                        textAnchor="middle"
                      >
                        {territory.allocatedDefenders.length}
                      </text>
                    </g>
                  )}

                  {/* Territory Name Tag */}
                  <text
                    x={0}
                    y={isCitadel ? 48 : 42}
                    fill={isSelected ? "#fbbf24" : isScorched ? "#64748b" : "#f8fafc"}
                    fontSize="12"
                    fontWeight="bold"
                    textAnchor="middle"
                    className="drop-shadow-md font-serif"
                  >
                    {territory.name}
                  </text>

                  {/* Status Subtitle */}
                  <text
                    x={0}
                    y={isCitadel ? 60 : 54}
                    fill={isDanger ? "#f87171" : isScorched ? "#475569" : "#94a3b8"}
                    fontSize="9"
                    fontWeight="semibold"
                    textAnchor="middle"
                  >
                    {isScorched
                      ? "[SCORCHED]"
                      : isDanger
                      ? "! BATTLE FRONT !"
                      : `Yield: +${territory.resourceYield}g | +${territory.faithYield ?? 10}f`}
                  </text>
                </g>
              </g>
            );
          })}
        </g>
      </svg>
    </div>
  );
};
</file>

<file path="src/features/logistics/RoundSummaryScreen.tsx">
import React from 'react';
import { useCampaign } from '../../context/CampaignContext';
import { ShieldCheck, Skull, Coins, Sparkles, ArrowRight, Building2, Flame } from 'lucide-react';
import { ErrorBoundary } from '../../components/ErrorBoundary';

interface Props {
  onProceedToEmpireManagement: () => void;
}

export const RoundSummaryScreen: React.FC<Props> = ({ onProceedToEmpireManagement }) => {
  const { territories, roundLog, doomClock, applyEndOfRoundYields } = useCampaign();

  const survivingTerritories = territories.filter(t => !t.isScorched);
  const scorchedTerritories = territories.filter(t => t.isScorched);

  const totalGoldYield = survivingTerritories.reduce((acc, t) => acc + (t.resourceYield || 0), 0);
  const totalFaithYield = survivingTerritories.reduce((acc, t) => acc + (t.faithYield || 0), 0);

  const handleProceed = () => {
    applyEndOfRoundYields();
    onProceedToEmpireManagement();
  };

  return (
    <ErrorBoundary>
      <div className="w-full h-full min-h-screen bg-slate-950 text-slate-100 flex flex-col justify-between p-6 md:p-12 select-none overflow-y-auto">
        <div className="max-w-4xl mx-auto w-full space-y-8">
          {/* Header Banner */}
          <div className="text-center space-y-2 border-b border-slate-800 pb-6">
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-950/80 border border-amber-800 text-amber-400 font-bold text-xs uppercase tracking-widest">
              <Sparkles className="w-4 h-4" /> Round Resolution Complete
            </div>
            <h1 className="text-3xl md:text-5xl font-black font-serif tracking-tight text-white">
              End of Round Tactical Report
            </h1>
            <p className="text-slate-400 text-sm md:text-base max-w-xl mx-auto">
              All frontline defense engagements for this cycle have concluded. Review territory status and collect empire yields.
            </p>
          </div>

          {/* Round Battles Log Section */}
          <div className="space-y-4">
            <h2 className="text-xs font-bold uppercase tracking-wider text-slate-400 flex items-center gap-2">
              <Building2 className="w-4 h-4 text-amber-400" /> Recent Engagements & Territory Status
            </h2>

            {roundLog.length === 0 ? (
              <div className="p-4 bg-slate-900 border border-slate-800 rounded-xl text-slate-400 text-sm italic">
                No active defense battles took place this round. Frontlines held without conflict.
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {roundLog.map((log, idx) => (
                  <div
                    key={`${log.territoryId}_${idx}`}
                    className={`p-4 rounded-xl border flex items-center justify-between shadow-lg ${
                      log.outcome === 'victory'
                        ? 'bg-emerald-950/30 border-emerald-900/80 text-emerald-200'
                        : 'bg-red-950/30 border-red-900/80 text-red-200'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      {log.outcome === 'victory' ? (
                        <ShieldCheck className="w-6 h-6 text-emerald-400" />
                      ) : (
                        <Flame className="w-6 h-6 text-red-500 animate-pulse" />
                      )}
                      <div>
                        <div className="font-bold text-base text-white">{log.territoryName}</div>
                        <div className="text-xs opacity-80">
                          {log.outcome === 'victory' ? 'Defended Successfully' : 'Surrendered / Fallen'}
                        </div>
                      </div>
                    </div>

                    {log.outcome === 'surrendered' && (
                      <span className="text-xs font-mono font-bold text-amber-400 bg-amber-950/80 px-2.5 py-1 rounded border border-amber-800">
                        +{log.goldEarned}g Salvage
                      </span>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* End of Round Yield Earnings Grid */}
          <div className="space-y-4">
            <h2 className="text-xs font-bold uppercase tracking-wider text-slate-400 flex items-center gap-2">
              <Coins className="w-4 h-4 text-yellow-400" /> End of Round Resource Earnings
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {/* Gold Yield */}
              <div className="bg-slate-900 border border-slate-800 p-5 rounded-2xl flex flex-col justify-between space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold uppercase tracking-wider text-slate-400">Total Gold Yield</span>
                  <Coins className="w-5 h-5 text-yellow-400" />
                </div>
                <div className="text-3xl font-black text-yellow-400">+{totalGoldYield} Gold</div>
                <div className="text-xs text-slate-500">From {survivingTerritories.length} surviving territories & production infrastructure</div>
              </div>

              {/* Faith Yield */}
              <div className="bg-slate-900 border border-slate-800 p-5 rounded-2xl flex flex-col justify-between space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold uppercase tracking-wider text-slate-400">Total Faith Yield</span>
                  <Sparkles className="w-5 h-5 text-cyan-400" />
                </div>
                <div className="text-3xl font-black text-cyan-400">+{totalFaithYield} Faith</div>
                <div className="text-xs text-slate-500">From divine sanctums and territory shrines</div>
              </div>

              {/* Empire Health / Doom Clock */}
              <div className="bg-slate-900 border border-slate-800 p-5 rounded-2xl flex flex-col justify-between space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold uppercase tracking-wider text-slate-400">Doom Clock Status</span>
                  <Skull className="w-5 h-5 text-red-500" />
                </div>
                <div className="text-3xl font-black text-red-500">
                  {doomClock <= 1 ? 'DOOMSDAY IS COMING!' : `${doomClock} Cycles Remaining`}
                </div>
                <div className="text-xs text-slate-500">{scorchedTerritories.length} of {territories.length} cities have fallen</div>
              </div>
            </div>
          </div>
        </div>

        {/* Bottom Proceed Action Button */}
        <div className="max-w-4xl mx-auto w-full pt-8 border-t border-slate-800">
          <button
            onClick={handleProceed}
            className="w-full py-4 bg-amber-600 hover:bg-amber-500 text-black font-black uppercase tracking-widest rounded-xl text-base md:text-lg shadow-xl hover:scale-[1.01] transition-all flex items-center justify-center gap-3"
          >
            Collect Yields & Return to Empire Management <ArrowRight className="w-5 h-5" />
          </button>
        </div>
      </div>
    </ErrorBoundary>
  );
};
</file>

<file path="src/features/logistics/TerritoryDetailPanel.tsx">
import React, { useState } from 'react';
import type { Territory, UnitTemplate } from '../../types/combat';
import type { EmporiumItem } from '../../types/game';
import { Flame, Shield, Coins, Users, Skull, ChevronRight, BarChart3 } from 'lucide-react';
import { EmpireOverviewPanel } from './EmpireOverviewPanel';

interface Props {
  territory: Territory | null;
  territories: Territory[];
  globalUnitPool: UnitTemplate[];
  gold: number;
  faith: number;
  doomClock: number;
  emporiumItems: EmporiumItem[];
  purchasedItemIds: string[];
  onUpgradeBuilding: (territoryId: string, buildingId: string) => void;
  onScorchTerritory: (territoryId: string) => void;
  onOpenUnitManager: (territoryId: string) => void;
}

export const TerritoryDetailPanel: React.FC<Props> = ({
  territory,
  territories,
  globalUnitPool,
  gold,
  faith,
  doomClock,
  emporiumItems,
  purchasedItemIds,
  onUpgradeBuilding,
  onScorchTerritory,
  onOpenUnitManager,
}) => {
  const [panelTab, setPanelTab] = useState<'city' | 'overview'>('city');

  if (panelTab === 'overview') {
    return (
      <div className="w-full h-full flex flex-col bg-slate-900 overflow-hidden select-none">
        {/* Toggle Bar */}
        <div className="flex bg-slate-950 p-2 border-b border-slate-800 gap-2">
          <button
            onClick={() => setPanelTab('city')}
            className="flex-1 py-1.5 rounded-lg text-xs font-bold text-slate-400 hover:text-slate-200 bg-slate-900 border border-slate-800 transition-colors flex items-center justify-center gap-1.5"
          >
            <Shield className="w-3.5 h-3.5" /> City Details
          </button>
          <button
            onClick={() => setPanelTab('overview')}
            className="flex-1 py-1.5 rounded-lg text-xs font-bold text-amber-300 bg-amber-950/80 border border-amber-800 transition-colors flex items-center justify-center gap-1.5 shadow"
          >
            <BarChart3 className="w-3.5 h-3.5" /> Empire Overview
          </button>
        </div>

        <EmpireOverviewPanel
          territories={territories}
          globalUnitPool={globalUnitPool}
          gold={gold}
          faith={faith}
          doomClock={doomClock}
          emporiumItems={emporiumItems}
          purchasedItemIds={purchasedItemIds}
        />
      </div>
    );
  }

  if (!territory) {
    return (
      <div className="w-full h-full flex flex-col bg-slate-900 overflow-hidden select-none">
        {/* Toggle Bar */}
        <div className="flex bg-slate-950 p-2 border-b border-slate-800 gap-2">
          <button
            onClick={() => setPanelTab('city')}
            className="flex-1 py-1.5 rounded-lg text-xs font-bold text-amber-300 bg-slate-800 border border-slate-700 transition-colors flex items-center justify-center gap-1.5"
          >
            <Shield className="w-3.5 h-3.5" /> City Details
          </button>
          <button
            onClick={() => setPanelTab('overview')}
            className="flex-1 py-1.5 rounded-lg text-xs font-bold text-slate-400 hover:text-slate-200 bg-slate-900 border border-slate-800 transition-colors flex items-center justify-center gap-1.5"
          >
            <BarChart3 className="w-3.5 h-3.5" /> Empire Overview
          </button>
        </div>

        <div className="flex-1 flex items-center justify-center p-6 text-slate-500 text-sm italic">
          Select a territory node on the map to view details.
        </div>
      </div>
    );
  }

  const isDanger = territory.hasActiveBattle;
  const isScorched = territory.isScorched;

  return (
    <div className="w-full h-full flex flex-col bg-slate-900 overflow-hidden select-none">
      {/* Toggle Bar */}
      <div className="flex bg-slate-950 p-2 border-b border-slate-800 gap-2">
        <button
          onClick={() => setPanelTab('city')}
          className="flex-1 py-1.5 rounded-lg text-xs font-bold text-amber-300 bg-slate-800 border border-slate-700 transition-colors flex items-center justify-center gap-1.5 shadow"
        >
          <Shield className="w-3.5 h-3.5" /> City Details
        </button>
        <button
          onClick={() => setPanelTab('overview')}
          className="flex-1 py-1.5 rounded-lg text-xs font-bold text-slate-400 hover:text-slate-200 bg-slate-900 border border-slate-800 transition-colors flex items-center justify-center gap-1.5"
        >
          <BarChart3 className="w-3.5 h-3.5" /> Empire Overview
        </button>
      </div>

      {/* Panel Header */}
      <div className="p-4 bg-slate-950 border-b border-slate-800 flex justify-between items-start">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="text-xs uppercase font-bold tracking-widest px-2.5 py-0.5 rounded bg-slate-800 text-slate-300 border border-slate-700">
              Ring {territory.ringLevel} • {territory.type}
            </span>
            {isDanger && (
              <span className="text-xs uppercase font-black tracking-wider px-2 py-0.5 rounded bg-red-950 text-red-400 border border-red-800 flex items-center gap-1 animate-pulse">
                <Flame className="w-3.5 h-3.5" /> Front Line
              </span>
            )}
            {isScorched && (
              <span className="text-xs uppercase font-bold tracking-wider px-2 py-0.5 rounded bg-slate-800 text-slate-500 border border-slate-700">
                Scorched
              </span>
            )}
          </div>
          <h2 className="text-2xl font-bold font-serif text-white">{territory.name}</h2>
        </div>
      </div>

      {/* Scrollable Content (2 Side-by-Side Columns: Left = Gold Yield & Garrison, Right = Buildings) */}
      <div className="flex-1 overflow-y-auto p-4">
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
          {/* Left Column: Gold Yield & Garrisoned Defenders */}
          <div className="space-y-4">
            {/* City Yields Card (Stacked format identical to Empire Overview) */}
            <div className="bg-slate-950 p-3.5 rounded-xl border border-slate-800 space-y-1">
              <div className="text-xs text-slate-400 font-semibold uppercase flex items-center gap-1">
                <Coins className="w-3.5 h-3.5 text-yellow-400" /> City Yields
              </div>
              <div className="text-lg font-bold text-green-400 mt-1">+{territory.resourceYield}g Gold / turn</div>
              <div className="text-lg font-bold text-cyan-400 mt-0.5">+{territory.faithYield ?? 10} Faith / turn</div>
            </div>

            {/* Assigned Defenders Overview */}
            <div className="bg-slate-950 p-4 rounded-xl border border-slate-800">
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2 font-bold text-white text-sm uppercase tracking-wide">
                  <Users className="w-4 h-4 text-cyan-400" /> Garrisoned Defenders ({territory.allocatedDefenders.length})
                </div>
                <button
                  onClick={() => onOpenUnitManager(territory.id)}
                  className="text-xs font-bold text-amber-400 hover:text-amber-300 flex items-center gap-0.5"
                >
                  Manage <ChevronRight className="w-3.5 h-3.5" />
                </button>
              </div>

              {territory.allocatedDefenders.length === 0 ? (
                <div className="text-slate-500 text-xs italic py-2">No units assigned to this territory yet.</div>
              ) : (
                <div className="flex flex-wrap gap-2">
                  {Object.values(
                    territory.allocatedDefenders.reduce((acc, u) => {
                      if (!acc[u.name]) acc[u.name] = { name: u.name, count: 0 };
                      acc[u.name].count += 1;
                      return acc;
                    }, {} as Record<string, { name: string; count: number }>)
                  ).map(stack => (
                    <div
                      key={stack.name}
                      className="px-2.5 py-1 bg-slate-900 border border-slate-700 rounded text-xs text-slate-300 font-mono flex items-center gap-1.5"
                    >
                      <Shield className="w-3 h-3 text-amber-400" />
                      <span className="font-semibold text-white">{stack.name}</span>
                      <span className="text-amber-400 font-bold text-[11px]">x{stack.count}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Right Column: Town Infrastructure & Buildings */}
          <div className="space-y-3">
            <h3 className="text-sm font-bold uppercase tracking-wider text-slate-300 flex items-center gap-2">
              Town Infrastructure & Buildings ({territory.buildings?.length ?? 0})
            </h3>

            {!territory.buildings || territory.buildings.length === 0 ? (
              <div className="text-slate-500 text-xs italic bg-slate-950 p-4 rounded-xl border border-slate-800">
                No buildings constructed in this territory.
              </div>
            ) : (
              territory.buildings.map(b => {
                const isMax = b.level >= b.maxLevel;
                const canAfford = gold >= b.upgradeCost;
                const currentBonus = (b.level - 1) * 25;
                const nextBonus = b.level * 25;

                return (
                  <div
                    key={b.id}
                    className="bg-slate-950 p-4 rounded-xl border border-slate-800 flex flex-col gap-2"
                  >
                    <div className="flex justify-between items-start">
                      <div>
                        <h4 className="font-bold text-white text-base flex items-center gap-2">
                          {b.name}
                          <span className="text-xs px-2 py-0.5 bg-slate-800 text-amber-400 rounded font-mono">
                            Lv.{b.level}/{b.maxLevel}
                          </span>
                        </h4>
                        <p className="text-xs text-slate-400 mt-1">{b.effectDescription}</p>
                        {!isMax && (
                          <div className="text-xs font-semibold text-emerald-400 mt-1 flex items-center gap-1 font-mono">
                            Upgrade Effect: {b.type === 'production' ? `${currentBonus} → ${nextBonus} Gold per turn` : `Level ${b.level} → Level ${b.level + 1}`}
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="flex justify-between items-center mt-2 pt-2 border-t border-slate-800/80">
                      <span className="text-xs text-slate-400">
                        {isMax && (
                          <span className="text-amber-400 font-bold uppercase">MAX LEVEL</span>
                        )}
                      </span>

                      {!isScorched && !isMax && (
                        <button
                          onClick={() => onUpgradeBuilding(territory.id, b.id)}
                          disabled={!canAfford}
                          className={`px-3.5 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 transition-all ${
                            canAfford
                              ? 'bg-amber-500 hover:bg-amber-400 text-slate-950 shadow-md hover:scale-[1.02]'
                              : 'bg-slate-800 text-slate-500 cursor-not-allowed border border-slate-700'
                          }`}
                        >
                          <Coins className="w-3.5 h-3.5" /> Upgrade: ({b.upgradeCost} Gold)
                        </button>
                      )}
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>

      {/* Action Footer */}
      <div className="p-4 bg-slate-950 border-t border-slate-800 flex flex-col gap-2">
        {!isScorched ? (
          <>
            <button
              onClick={() => onOpenUnitManager(territory.id)}
              className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-white rounded-lg font-bold text-sm transition-colors flex items-center justify-center gap-2 border border-slate-700"
            >
              <Users className="w-4 h-4 text-cyan-400" /> Manage Troops ({territory.allocatedDefenders.length})
            </button>

            <button
              onClick={() => onScorchTerritory(territory.id)}
              className="w-full py-2.5 bg-red-950/80 hover:bg-red-900 border border-red-800/80 text-red-200 rounded-lg font-bold text-sm transition-colors flex items-center justify-center gap-2"
            >
              <Skull className="w-4 h-4 text-red-400" /> Scorched Earth (+1000g)
            </button>
          </>
        ) : (
          <div className="text-center text-red-500 font-bold py-3 uppercase tracking-widest text-sm bg-red-950/30 border border-red-900/40 rounded-lg">
            Territory Scorched
          </div>
        )}
      </div>
    </div>
  );
};
</file>

<file path="src/features/logistics/TerritoryDrawer.tsx">
import React from 'react';
import type { Territory } from '../../types/combat';
import { X, Flame, Shield, Coins, Users, Skull, ChevronRight } from 'lucide-react';

interface Props {
  territory: Territory | null;
  gold: number;
  onClose: () => void;
  onUpgradeBuilding: (territoryId: string, buildingId: string) => void;
  onScorchTerritory: (territoryId: string) => void;
  onOpenUnitManager: (territoryId: string) => void;
}

export const TerritoryDrawer: React.FC<Props> = ({
  territory,
  gold,
  onClose,
  onUpgradeBuilding,
  onScorchTerritory,
  onOpenUnitManager,
}) => {
  if (!territory) return null;

  const isDanger = territory.hasActiveBattle;
  const isScorched = territory.isScorched;

  return (
    <div className="fixed inset-y-0 right-0 w-full max-w-md bg-slate-900 border-l border-slate-700 shadow-2xl z-50 flex flex-col transform transition-transform duration-300 ease-in-out">
      {/* Drawer Header */}
      <div className="p-5 bg-slate-950 border-b border-slate-800 flex justify-between items-start">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="text-xs uppercase font-bold tracking-widest px-2.5 py-0.5 rounded bg-slate-800 text-slate-300 border border-slate-700">
              Ring {territory.ringLevel} • {territory.type}
            </span>
            {isDanger && (
              <span className="text-xs uppercase font-black tracking-wider px-2 py-0.5 rounded bg-red-950 text-red-400 border border-red-800 flex items-center gap-1 animate-pulse">
                <Flame className="w-3.5 h-3.5" /> Front Line
              </span>
            )}
            {isScorched && (
              <span className="text-xs uppercase font-bold tracking-wider px-2 py-0.5 rounded bg-slate-800 text-slate-500 border border-slate-700">
                Scorched
              </span>
            )}
          </div>
          <h2 className="text-2xl font-bold font-serif text-white">{territory.name}</h2>
        </div>
        <button
          onClick={onClose}
          className="p-1.5 text-slate-400 hover:text-white bg-slate-800 rounded-lg hover:bg-slate-700 transition-colors"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Drawer Scrollable Content */}
      <div className="flex-1 overflow-y-auto p-5 space-y-6">
        {/* Yield & Stats Box */}
        <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 text-center">
          <div className="text-xs text-slate-400 uppercase font-semibold">Territory Gold Yield</div>
          <div className="text-2xl font-bold text-green-400 mt-1">+{territory.resourceYield}g / turn</div>
        </div>

        {/* Assigned Defenders Overview */}
        <div className="bg-slate-950 p-4 rounded-xl border border-slate-800">
          <div className="flex justify-between items-center mb-3">
            <div className="flex items-center gap-2 font-bold text-white text-sm uppercase tracking-wide">
              <Users className="w-4 h-4 text-cyan-400" /> Garrisoned Defenders ({territory.allocatedDefenders.length})
            </div>
            <button
              onClick={() => onOpenUnitManager(territory.id)}
              className="text-xs font-bold text-amber-400 hover:text-amber-300 flex items-center gap-0.5"
            >
              Manage <ChevronRight className="w-3.5 h-3.5" />
            </button>
          </div>

          {territory.allocatedDefenders.length === 0 ? (
            <div className="text-slate-500 text-xs italic py-2">No units assigned to this territory yet.</div>
          ) : (
            <div className="flex flex-wrap gap-2">
              {Object.values(
                territory.allocatedDefenders.reduce((acc, u) => {
                  if (!acc[u.name]) acc[u.name] = { name: u.name, count: 0 };
                  acc[u.name].count += 1;
                  return acc;
                }, {} as Record<string, { name: string; count: number }>)
              ).map(stack => (
                <div
                  key={stack.name}
                  className="px-2.5 py-1 bg-slate-900 border border-slate-700 rounded text-xs text-slate-300 font-mono flex items-center gap-1.5"
                >
                  <Shield className="w-3 h-3 text-amber-400" />
                  <span className="font-semibold text-white">{stack.name}</span>
                  <span className="text-amber-400 font-bold text-[11px]">x{stack.count}</span>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Town Buildings Section */}
        <div className="space-y-3">
          <h3 className="text-sm font-bold uppercase tracking-wider text-slate-300 flex items-center gap-2">
            Town Infrastructure & Buildings ({territory.buildings?.length ?? 0})
          </h3>

          {!territory.buildings || territory.buildings.length === 0 ? (
            <div className="text-slate-500 text-xs italic bg-slate-950 p-4 rounded-xl border border-slate-800">
              No buildings constructed in this territory.
            </div>
          ) : (
            territory.buildings.map(b => {
              const isMax = b.level >= b.maxLevel;
              const canAfford = gold >= b.upgradeCost;
              const currentBonus = (b.level - 1) * 25;
              const nextBonus = b.level * 25;

              return (
                <div
                  key={b.id}
                  className="bg-slate-950 p-4 rounded-xl border border-slate-800 flex flex-col gap-2"
                >
                  <div className="flex justify-between items-start">
                    <div>
                      <h4 className="font-bold text-white text-base flex items-center gap-2">
                        {b.name}
                        <span className="text-xs px-2 py-0.5 bg-slate-800 text-amber-400 rounded font-mono">
                          Lv.{b.level}/{b.maxLevel}
                        </span>
                      </h4>
                      <p className="text-xs text-slate-400 mt-1">{b.effectDescription}</p>
                      {!isMax && (
                        <div className="text-xs font-semibold text-emerald-400 mt-1 flex items-center gap-1 font-mono">
                          Upgrade Effect: {b.type === 'production' ? `${currentBonus} → ${nextBonus} Gold per turn` : `Level ${b.level} → Level ${b.level + 1}`}
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex justify-between items-center mt-2 pt-2 border-t border-slate-800/80">
                    <span className="text-xs text-slate-400">
                      {isMax && (
                        <span className="text-amber-400 font-bold uppercase">MAX LEVEL</span>
                      )}
                    </span>

                    {!isScorched && !isMax && (
                      <button
                        onClick={() => onUpgradeBuilding(territory.id, b.id)}
                        disabled={!canAfford}
                        className={`px-3.5 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 transition-all ${
                          canAfford
                            ? 'bg-amber-500 hover:bg-amber-400 text-slate-950 shadow-md hover:scale-[1.02]'
                            : 'bg-slate-800 text-slate-500 cursor-not-allowed border border-slate-700'
                        }`}
                      >
                        <Coins className="w-3.5 h-3.5" /> Upgrade: ({b.upgradeCost} Gold)
                      </button>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* Drawer Action Footer */}
      <div className="p-4 bg-slate-950 border-t border-slate-800 flex flex-col gap-2">
        {!isScorched ? (
          <>
            <button
              onClick={() => onOpenUnitManager(territory.id)}
              className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-white rounded-lg font-bold text-sm transition-colors flex items-center justify-center gap-2 border border-slate-700"
            >
              <Users className="w-4 h-4 text-cyan-400" /> Manage Troops ({territory.allocatedDefenders.length})
            </button>

            <button
              onClick={() => onScorchTerritory(territory.id)}
              className="w-full py-2.5 bg-red-950/80 hover:bg-red-900 border border-red-800/80 text-red-200 rounded-lg font-bold text-sm transition-colors flex items-center justify-center gap-2"
            >
              <Skull className="w-4 h-4 text-red-400" /> Scorched Earth (+1000g)
            </button>
          </>
        ) : (
          <div className="text-center text-red-500 font-bold py-3 uppercase tracking-widest text-sm bg-red-950/30 border border-red-900/40 rounded-lg">
            Territory Scorched
          </div>
        )}
      </div>
    </div>
  );
};
</file>

<file path="src/features/logistics/UnitLogisticsModal.tsx">
import React, { useState } from 'react';
import type { Territory, UnitTemplate } from '../../types/combat';
import { UNIT_ROSTER } from '../../data/units';
import { X, Users, Coins, Shield, ArrowLeftRight } from 'lucide-react';

interface Props {
  territories: Territory[];
  globalUnitPool: UnitTemplate[];
  gold: number;
  initialTerritoryId?: string | null;
  onClose: () => void;
  onAllocateUnit: (territoryId: string, unitId: string) => void;
  onDeallocateUnit: (territoryId: string, unitId: string) => void;
  onBuyUnit: (unitTemplateId: string) => void;
  onTransferUnits: (fromId: string, toId: string, unitIds: string[]) => void;
}

type UnitStack = {
  name: string;
  type: string;
  hp: number;
  damage: number;
  range: number;
  units: UnitTemplate[];
};

// Non-hero unit templates available for purchase in the recruitment store
const PURCHASABLE_UNITS = UNIT_ROSTER.filter(u => u.type !== 'hero');

export const UnitLogisticsModal: React.FC<Props> = ({
  territories,
  globalUnitPool,
  gold,
  initialTerritoryId,
  onClose,
  onAllocateUnit,
  onDeallocateUnit,
  onBuyUnit,
  onTransferUnits,
}) => {
  const activeTerritories = territories.filter(t => !t.isScorched);
  const [selectedTerritoryId, setSelectedTerritoryId] = useState<string>(
    initialTerritoryId || (activeTerritories[0]?.id ?? '')
  );

  const selectedTerritory = territories.find(t => t.id === selectedTerritoryId);

  // Group Global Pool Units into Stack Map
  const poolStackMap: Record<string, UnitTemplate[]> = {};
  globalUnitPool.forEach(u => {
    if (!poolStackMap[u.name]) poolStackMap[u.name] = [];
    poolStackMap[u.name].push(u);
  });

  // Group Assigned Garrison Units into Stack Cards
  const assignedDefenders = selectedTerritory ? selectedTerritory.allocatedDefenders : [];
  const assignedStacks: UnitStack[] = Object.values(
    assignedDefenders.reduce<Record<string, UnitStack>>((acc, u) => {
      if (!acc[u.name]) {
        acc[u.name] = { name: u.name, type: u.type, hp: u.hp, damage: u.damage, range: u.range, units: [] };
      }
      acc[u.name].units.push(u);
      return acc;
    }, {})
  );

  const handleTransferAllToGarrison = () => {
    if (!selectedTerritory || globalUnitPool.length === 0) return;
    const allIds = globalUnitPool.map(u => u.id);
    onTransferUnits('reserve', selectedTerritory.id, allIds);
  };

  const handleReturnAllToReserve = () => {
    if (!selectedTerritory || selectedTerritory.allocatedDefenders.length === 0) return;
    const allIds = selectedTerritory.allocatedDefenders.map(u => u.id);
    onTransferUnits(selectedTerritory.id, 'reserve', allIds);
  };

  const handleTransferStackToGarrison = (units: UnitTemplate[]) => {
    if (!selectedTerritory || units.length === 0) return;
    onTransferUnits('reserve', selectedTerritory.id, units.map(u => u.id));
  };

  const handleReturnStackToReserve = (stack: UnitStack) => {
    if (!selectedTerritory || stack.units.length === 0) return;
    onTransferUnits(selectedTerritory.id, 'reserve', stack.units.map(u => u.id));
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4 sm:p-6 select-none">
      <div className="bg-slate-900 border border-slate-700 rounded-2xl max-w-5xl w-full p-6 relative shadow-2xl flex flex-col max-h-[90vh]">
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 rounded-full transition-colors"
        >
          <X className="w-5 h-5" />
        </button>

        {/* Modal Header */}
        <div className="mb-4">
          <h2 className="text-2xl font-bold font-serif text-white flex items-center gap-2">
            <Users className="w-6 h-6 text-amber-400" />
            Allocate Troops to {selectedTerritory ? selectedTerritory.name : 'Territory'}
          </h2>
          <p className="text-slate-400 text-sm">
            Recruit fresh reinforcements directly into your reserve pool and deploy unit stacks to garrisons.
          </p>
        </div>

        {/* Split View Content (2 Side-by-Side Columns) */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 flex-1 overflow-y-auto min-h-0">
          {/* Left Column: Available Pool & Integrated Recruitment Shop */}
          <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 flex flex-col space-y-3">
            <div className="flex justify-between items-center pb-2 border-b border-slate-800 flex-shrink-0">
              <h4 className="text-sm font-bold uppercase tracking-wider text-cyan-400 flex items-center gap-1.5">
                <Users className="w-4 h-4" /> Available Pool ({globalUnitPool.length})
              </h4>
              {selectedTerritory && globalUnitPool.length > 0 && (
                <button
                  onClick={handleTransferAllToGarrison}
                  className="text-xs px-2.5 py-1 bg-cyan-950 hover:bg-cyan-900 border border-cyan-700 text-cyan-300 font-bold rounded transition-colors flex items-center gap-1"
                >
                  <ArrowLeftRight className="w-3 h-3" /> Deploy All ({globalUnitPool.length})
                </button>
              )}
            </div>

            {/* Integrated Unit Roster Cards */}
            <div className="flex-1 overflow-y-auto space-y-3 pr-1">
              {PURCHASABLE_UNITS.map(template => {
                const reserveUnits = poolStackMap[template.name] || [];
                const canAfford = gold >= template.cost;

                return (
                  <div
                    key={template.id}
                    className="bg-slate-900 p-3 rounded-xl border border-slate-800 hover:border-slate-700 transition-colors flex flex-col gap-2.5 shadow-sm"
                  >
                    <div className="flex justify-between items-start">
                      <div>
                        <div className="font-bold text-white text-sm flex items-center gap-2">
                          {template.name}
                          <span className="text-[10px] px-1.5 py-0.2 rounded bg-slate-800 text-slate-400 uppercase font-mono">
                            {template.type}
                          </span>
                        </div>
                        <div className="text-[11px] text-slate-400 uppercase mt-0.5">
                          HP: {template.hp} | DMG: {template.damage} | Range: {template.range}
                        </div>
                      </div>

                      <div className="text-right">
                        <span className="text-xs font-bold text-amber-300 font-mono px-2 py-0.5 bg-amber-500/10 border border-amber-500/30 rounded">
                          x{reserveUnits.length} in reserve
                        </span>
                      </div>
                    </div>

                    <div className="flex justify-between items-center pt-2 border-t border-slate-800/80">
                      <div className="flex items-center gap-1">
                        {selectedTerritory && (
                          <div className="flex items-center gap-1 bg-slate-950 px-2 py-1 rounded border border-slate-800 text-xs">
                            <span className="text-slate-400 font-bold mr-1">Deploy:</span>
                            <button
                              onClick={() => reserveUnits.length > 0 && onAllocateUnit(selectedTerritory.id, reserveUnits[0].id)}
                              disabled={reserveUnits.length === 0}
                              className={`px-2 py-0.5 font-bold text-xs rounded transition-colors ${
                                reserveUnits.length > 0
                                  ? 'bg-green-900/80 hover:bg-green-700 text-green-200'
                                  : 'bg-slate-800 text-slate-600 cursor-not-allowed'
                              }`}
                              title="Assign to territory"
                            >
                              1
                            </button>
                            {reserveUnits.length > 1 && (
                              <button
                                onClick={() => handleTransferStackToGarrison(reserveUnits)}
                                className="px-2 py-0.5 bg-cyan-900/80 hover:bg-cyan-700 text-cyan-200 text-xs font-bold rounded transition-colors"
                              >
                                All ({reserveUnits.length})
                              </button>
                            )}
                          </div>
                        )}
                      </div>

                      <button
                        onClick={() => onBuyUnit(template.id)}
                        disabled={!canAfford}
                        className={`px-3 py-1 rounded font-bold text-xs flex items-center gap-1 transition-all ${
                          canAfford
                            ? 'bg-amber-600 hover:bg-amber-500 text-black shadow-md'
                            : 'bg-slate-800 text-slate-500 cursor-not-allowed'
                        }`}
                      >
                        <Coins className="w-3.5 h-3.5" /> Recruit ({template.cost}g)
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Right Column: Assigned Garrison Pool (With Target Selector Tabs at top of Header) */}
          <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 flex flex-col space-y-3">
            <div className="pb-3 border-b border-slate-800 flex-shrink-0 space-y-2">
              <div className="flex justify-between items-center">
                <h4 className="text-sm font-bold uppercase tracking-wider text-amber-400 flex items-center gap-1.5">
                  <Shield className="w-4 h-4" /> Assigned ({assignedDefenders.length})
                </h4>
                {selectedTerritory && assignedDefenders.length > 0 && (
                  <button
                    onClick={handleReturnAllToReserve}
                    className="text-xs px-2.5 py-1 bg-red-950 hover:bg-red-900 border border-red-800 text-red-300 font-bold rounded transition-colors flex items-center gap-1"
                  >
                    <ArrowLeftRight className="w-3 h-3" /> Recall All ({assignedDefenders.length})
                  </button>
                )}
              </div>

              {/* Target Territory Tabs inside Assigned Garrison Box Header */}
              <div className="flex flex-wrap items-center gap-1 bg-slate-900 p-1.5 rounded-lg border border-slate-800">
                <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 mr-1 ml-1">Target City:</span>
                {activeTerritories.map(t => {
                  const isSelected = t.id === selectedTerritoryId;
                  return (
                    <button
                      key={t.id}
                      onClick={() => setSelectedTerritoryId(t.id)}
                      className={`px-2 py-0.5 rounded text-xs font-bold transition-all flex items-center gap-1 ${
                        isSelected
                          ? 'bg-amber-600 text-black shadow-md'
                          : 'bg-slate-950 hover:bg-slate-800 text-slate-400 border border-slate-800'
                      }`}
                    >
                      <Shield className="w-3 h-3" /> {t.name} ({t.allocatedDefenders.length})
                    </button>
                  );
                })}
              </div>
            </div>

            {!selectedTerritory ? (
              <div className="text-slate-500 text-sm italic py-4 text-center">
                Select a territory above to manage its garrison.
              </div>
            ) : assignedStacks.length === 0 ? (
              <div className="text-slate-600 text-sm italic py-8 text-center flex flex-col items-center justify-center flex-1 gap-2">
                <Shield className="w-8 h-8 text-slate-800" />
                No defenders assigned to {selectedTerritory.name} yet.
              </div>
            ) : (
              <div className="flex-1 overflow-y-auto space-y-2.5 pr-1">
                {assignedStacks.map(stack => (
                  <div
                    key={stack.name}
                    className="flex justify-between items-center bg-slate-900 p-3 rounded-xl border border-slate-800 hover:border-slate-700 text-xs transition-colors shadow-sm"
                  >
                    <div>
                      <div className="font-bold text-white flex items-center gap-1.5">
                        {stack.name}
                        <span className="text-[11px] px-1.5 py-0.2 rounded bg-cyan-500/20 text-cyan-300 font-bold font-mono border border-cyan-500/30">
                          x{stack.units.length}
                        </span>
                        <span className="text-[10px] px-1.5 py-0.2 rounded bg-slate-800 text-slate-400 uppercase">
                          {stack.type}
                        </span>
                      </div>
                      <div className="text-[11px] text-slate-400 uppercase mt-0.5">
                        HP: {stack.hp} | DMG: {stack.damage}
                      </div>
                    </div>
                  {/* Standardised Recall Action */}
                  {stack.name === 'City Militia' || stack.name === 'Garrison Soldier' || stack.units[0]?.abilities?.includes('Fixed Garrison') ? (
                    <span
                      className="px-2 py-1 bg-slate-800/80 border border-slate-700 text-slate-400 text-[11px] font-bold rounded cursor-not-allowed"
                      title={`${stack.name} are bound to defend their homeland and cannot be reassigned`}
                    >
                      Fixed Garrison
                    </span>
                  ) : (
                    <div className="flex items-center gap-1 bg-slate-950 px-2 py-1 rounded border border-slate-800 text-xs">
                      <span className="text-slate-400 font-bold mr-1">Recall:</span>
                      <button
                        onClick={() => onDeallocateUnit(selectedTerritory.id, stack.units[0].id)}
                        className="px-2 py-0.5 bg-red-900/80 hover:bg-red-700 text-red-200 font-bold text-xs rounded transition-colors"
                        title="Remove from territory"
                      >
                        1
                      </button>
                      {stack.units.length > 1 && (
                        <button
                          onClick={() => handleReturnStackToReserve(stack)}
                          className="px-2 py-0.5 bg-red-950 hover:bg-red-900 border border-red-800 text-red-300 text-xs font-bold rounded transition-colors"
                        >
                          All ({stack.units.length})
                        </button>
                      )}
                    </div>
                  )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Modal Action Footer */}
        <div className="mt-6 flex justify-end">
          <button
            onClick={onClose}
            className="px-8 py-2.5 bg-amber-600 hover:bg-amber-500 text-black font-bold uppercase tracking-wider rounded-lg shadow-lg transition-transform hover:scale-105"
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
};
</file>

