<file path="src/tests/garrisonSoldier.test.tsx">
import { describe, it, expect } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import React from 'react';
import { CampaignProvider, useCampaign } from '../context/CampaignContext';

describe('Garrison Soldier behavior', () => {
  it('initializes all territories with 3 Garrison Soldier units', () => {
    const wrapper = ({ children }: { children: React.ReactNode }) => (
      <CampaignProvider>{children}</CampaignProvider>
    );
    const { result } = renderHook(() => useCampaign(), { wrapper });

    result.current.territories.forEach(territory => {
      const garrisonSoldiers = territory.allocatedDefenders.filter(u => u.name === 'Garrison Soldier');
      expect(garrisonSoldiers.length).toBe(3);
    });
  });

  it('prevents deallocating Garrison Soldiers from territories', () => {
    const wrapper = ({ children }: { children: React.ReactNode }) => (
      <CampaignProvider>{children}</CampaignProvider>
    );
    const { result } = renderHook(() => useCampaign(), { wrapper });

    const targetTerritory = result.current.territories[0];
    const garrisonUnit = targetTerritory.allocatedDefenders.find(u => u.name === 'Garrison Soldier')!;

    const initialDefenderCount = targetTerritory.allocatedDefenders.length;
    const initialPoolCount = result.current.globalUnitPool.length;

    act(() => {
      result.current.deallocateUnitFromTerritory(targetTerritory.id, garrisonUnit.id);
    });

    const updatedTerritory = result.current.territories.find(t => t.id === targetTerritory.id);
    expect(updatedTerritory?.allocatedDefenders.length).toBe(initialDefenderCount);
    expect(result.current.globalUnitPool.length).toBe(initialPoolCount);
  });

  it('prevents transferring Garrison Soldiers between territories', () => {
    const wrapper = ({ children }: { children: React.ReactNode }) => (
      <CampaignProvider>{children}</CampaignProvider>
    );
    const { result } = renderHook(() => useCampaign(), { wrapper });

    const sourceTerritory = result.current.territories[0];
    const destTerritory = result.current.territories[1];
    const garrisonUnit = sourceTerritory.allocatedDefenders.find(u => u.name === 'Garrison Soldier')!;

    const sourceInitialCount = sourceTerritory.allocatedDefenders.length;
    const destInitialCount = destTerritory.allocatedDefenders.length;

    act(() => {
      result.current.transferUnits(sourceTerritory.id, destTerritory.id, [garrisonUnit.id]);
    });

    const updatedSource = result.current.territories.find(t => t.id === sourceTerritory.id);
    const updatedDest = result.current.territories.find(t => t.id === destTerritory.id);

    expect(updatedSource?.allocatedDefenders.length).toBe(sourceInitialCount);
    expect(updatedDest?.allocatedDefenders.length).toBe(destInitialCount);
  });
});
</file>

<file path="src/tests/gridIsolation.test.tsx">
import { describe, it, expect } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import React from 'react';
import { CampaignProvider, useCampaign } from '../context/CampaignContext';

import { UNIT_ROSTER } from '../data/units';

describe('Location-Unique Deployment Grid Isolation', () => {
  it('isolates sandbox grid position updates from city territory grids', () => {
    const wrapper = ({ children }: { children: React.ReactNode }) => (
      <CampaignProvider>{children}</CampaignProvider>
    );
    const { result } = renderHook(() => useCampaign(), { wrapper });

    const cityTerritory = result.current.territories[0];
    const initialCityDefendersCount = cityTerritory.allocatedDefenders.length;

    // Place a unit on Sandbox grid
    act(() => {
      result.current.updateUnitGridPosition('sandbox', 'sandbox_unit_1', { x: 2, y: 3 }, UNIT_ROSTER[0]);
    });

    // Sandbox grid should contain the unit
    expect(result.current.sandboxDefenders.some(u => u.id === 'sandbox_unit_1')).toBe(true);

    // City territory defenders should remain untouched
    const updatedCityTerritory = result.current.territories.find(t => t.id === cityTerritory.id);
    expect(updatedCityTerritory?.allocatedDefenders.length).toBe(initialCityDefendersCount);
    expect(updatedCityTerritory?.allocatedDefenders.some(u => u.id === 'sandbox_unit_1')).toBe(false);
  });

  it('maintains independent grid positions for each city territory', () => {
    const wrapper = ({ children }: { children: React.ReactNode }) => (
      <CampaignProvider>{children}</CampaignProvider>
    );
    const { result } = renderHook(() => useCampaign(), { wrapper });

    const city1 = result.current.territories[0];
    const city2 = result.current.territories[1];

    const unitInCity1 = city1.allocatedDefenders[0];

    // Place unit in City 1 grid
    act(() => {
      result.current.updateUnitGridPosition(city1.id, unitInCity1.id, { x: 1, y: 1 });
    });

    // Unit in City 1 has gridPosition (1,1)
    const updatedCity1 = result.current.territories.find(t => t.id === city1.id);
    expect(updatedCity1?.allocatedDefenders.find(u => u.id === unitInCity1.id)?.gridPosition).toEqual({ x: 1, y: 1 });

    // City 2 defenders are unmodified
    const updatedCity2 = result.current.territories.find(t => t.id === city2.id);
    expect(updatedCity2?.allocatedDefenders.some(u => u.id === unitInCity1.id)).toBe(false);
  });
});
</file>

<file path="src/tests/preBattleSetup.test.tsx">
import { describe, it, expect } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { PreBattleSetup } from '../features/combat/PreBattleSetup';
import { CampaignProvider } from '../context/CampaignContext';

describe('PreBattleSetup Deployment Grid Logic', () => {
  it('handles Case 1 (Empty cell + unit selected -> deploy)', () => {
    render(
      <CampaignProvider>
        <PreBattleSetup isSandboxMode={true} />
      </CampaignProvider>
    );

    // Select first unit stack card from bench
    const benchCard = screen.getByText('Vanguard Spearman').closest('button');
    expect(benchCard).not.toBeNull();
    fireEvent.click(benchCard!);

    // Click cell (0,0)
    const cell00 = screen.getByText('0,0').closest('button');
    expect(cell00).not.toBeNull();
    fireEvent.click(cell00!);

    // Cell (0,0) should now display Vanguard Spearman (and no longer render text "0,0")
    expect(screen.queryByText('0,0')).toBeNull();
    expect(screen.getAllByText('Vanguard Spearman').length).toBeGreaterThan(0);
  });

  it('handles Case 2 (Occupied cell + different unit selected -> swap/return)', () => {
    render(
      <CampaignProvider>
        <PreBattleSetup isSandboxMode={true} />
      </CampaignProvider>
    );

    // 1. Select Spearman and deploy to (0,0)
    const spearmanCard = screen.getAllByText('Vanguard Spearman')[0].closest('button');
    fireEvent.click(spearmanCard!);
    const cell00 = screen.getByText('0,0').closest('button');
    fireEvent.click(cell00!);

    expect(screen.getAllByText('Vanguard Spearman').length).toBeGreaterThan(0);

    // 2. Select Crossbow from bench
    const crossbowCard = screen.getAllByText('Iron Crossbow')[0].closest('button');
    fireEvent.click(crossbowCard!);

    // 3. Click occupied cell (0,0) with Crossbow selected
    fireEvent.click(cell00!);

    // Cell (0,0) should now be occupied by Iron Crossbow
    expect(screen.getAllByText('Iron Crossbow').length).toBeGreaterThan(0);
  });

  it('retains unit selection across placements until no units remain in stack', () => {
    render(
      <CampaignProvider>
        <PreBattleSetup isSandboxMode={true} />
      </CampaignProvider>
    );

    // Select Hero card (Aric the Shieldbreaker, quantity = 1)
    const heroCard = screen.getAllByText('Aric the Shieldbreaker')[0].closest('button');
    fireEvent.click(heroCard!);

    // Deploy to (0,0)
    const cell00 = screen.getByText('0,0').closest('button');
    fireEvent.click(cell00!);

    // Since Hero had quantity 1, after placement there are 0 left in stack so it should be unselected
