import React, { createContext, useContext, useEffect, useState } from 'react';
import type { Settings } from '../types/game';

interface SettingsContextType {
  settings: Settings;
  updateSettings: (newSettings: Partial<Settings>) => void;
}

const defaultSettings: Settings = {
  masterVolume: 100,
  sfxVolume: 100,
  characterVolume: 100,
  bgmVolume: 100,
  isMuted: false,
  isSfxMuted: false,
  isCharacterMuted: false,
  isBgmMuted: false,
  theme: 'slate',
};

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

export const SettingsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('direct-strike-settings');
    if (saved) {
      try {
        const parsed = JSON.parse(saved) as Partial<Settings>;
        // Merge field-by-field with nullish coalescing so stale saves
        // never produce undefined for newly added fields.
        return {
          masterVolume: parsed.masterVolume ?? defaultSettings.masterVolume,
          sfxVolume: parsed.sfxVolume ?? defaultSettings.sfxVolume,
          characterVolume: parsed.characterVolume ?? defaultSettings.characterVolume,
          bgmVolume: parsed.bgmVolume ?? defaultSettings.bgmVolume,
          isMuted: parsed.isMuted ?? defaultSettings.isMuted,
          isSfxMuted: parsed.isSfxMuted ?? defaultSettings.isSfxMuted,
          isCharacterMuted: parsed.isCharacterMuted ?? defaultSettings.isCharacterMuted,
          isBgmMuted: parsed.isBgmMuted ?? defaultSettings.isBgmMuted,
          theme: parsed.theme ?? defaultSettings.theme,
        };
      } catch (e) {
        return defaultSettings;
      }
    }
    return defaultSettings;
  });

  useEffect(() => {
    localStorage.setItem('direct-strike-settings', JSON.stringify(settings));
    document.documentElement.setAttribute('data-theme', settings.theme);
  }, [settings]);

  const updateSettings = (newSettings: Partial<Settings>) => {
    setSettings((prev) => ({ ...prev, ...newSettings }));
  };

  return (
    <SettingsContext.Provider value={{ settings, updateSettings }}>
      {children}
    </SettingsContext.Provider>
  );
};

export const useSettings = () => {
  const context = useContext(SettingsContext);
  if (!context) {
    throw new Error('useSettings must be used within a SettingsProvider');
  }
  return context;
};
</file>

<file path="src/core/entities/UnitEntity.ts">
import type { Unit, BattlefieldZoneConfig } from '../../types/combat';
import { DEFAULT_BATTLEFIELD_ZONES } from '../../types/combat';
import { getDistance, getDirection } from '../math/utils';

export interface SimulationContext {
  canvasWidth: number;
  canvasHeight: number;
  defenders: UnitEntity[];
  horde: UnitEntity[];
  onDealDamage: (attacker: Unit, target: Unit, damage: number) => void;
  now: number;
  zoneConfig?: BattlefieldZoneConfig;
}

export interface UnitBehaviorState {
  name: string;
  update(entity: UnitEntity, deltaTimeSec: number, context?: SimulationContext): void;
}



export class DefenderHoldState implements UnitBehaviorState {
  name = 'DefenderHold';

  update(entity: UnitEntity, deltaTimeSec: number, context?: SimulationContext): void {
    const unit = entity.data;
    if (!context) return;

    const zoneConfig = context.zoneConfig || DEFAULT_BATTLEFIELD_ZONES;
    const playerAreaWidth = context.canvasWidth * zoneConfig.playerAreaRatio;

    // Scan for breached Horde units entering Player Area (x <= 40% width)
    const breachedEnemies = context.horde.filter(
      h => h.data.hp > 0 && h.data.x <= playerAreaWidth
    );

    if (breachedEnemies.length > 0) {
      entity.setState(new DefenderEngageState());
      entity.update(deltaTimeSec, context);
      return;
    }

    // Return to home position if set and not engaged
    if (unit.homeX !== undefined && unit.homeY !== undefined) {
      const { dx, dy, dist } = getDirection(unit.x, unit.y, unit.homeX, unit.homeY);
      if (dist > 5) {
        const moveDist = unit.speed * deltaTimeSec;
        unit.x += dx * moveDist;
        unit.y += dy * moveDist;
      }
    }
  }
}

export class DefenderEngageState implements UnitBehaviorState {
  name = 'DefenderEngage';

  update(entity: UnitEntity, deltaTimeSec: number, context?: SimulationContext): void {
    const unit = entity.data;
    if (!context) return;

    const zoneConfig = context.zoneConfig || DEFAULT_BATTLEFIELD_ZONES;
    const playerAreaWidth = context.canvasWidth * zoneConfig.playerAreaRatio;

    let nearestTarget: UnitEntity | null = null;
    let minDist = Infinity;

    context.horde.forEach(h => {
      if (h.data.hp > 0 && h.data.x <= playerAreaWidth + 30) {
        const dist = getDistance(unit.x, unit.y, h.data.x, h.data.y);
        if (dist < minDist) {
          minDist = dist;
          nearestTarget = h;
        }
      }
    });

    if (!nearestTarget) {
      unit.targetId = undefined;
      entity.setState(new DefenderHoldState());
      return;
    }

    const targetUnit = (nearestTarget as UnitEntity).data;
    unit.targetId = targetUnit.id;

    if (minDist <= unit.attackRange) {
      entity.setState(new AttackState(targetUnit.id));
      entity.update(deltaTimeSec, context);
      return;
    }

    const moveDist = unit.speed * deltaTimeSec;
    const { dx, dy } = getDirection(unit.x, unit.y, targetUnit.x, targetUnit.y);

    unit.x += dx * moveDist;
    unit.y += dy * moveDist;
  }
}

export class HordeMarchState implements UnitBehaviorState {
  name = 'HordeMarch';

  update(entity: UnitEntity, deltaTimeSec: number, context?: SimulationContext): void {
    const unit = entity.data;
    if (!context) {
      unit.x -= deltaTimeSec * 50;
      return;
    }

    let nearestTarget: UnitEntity | null = null;
    let minDist = Infinity;

    context.defenders.forEach(d => {
      if (d.data.hp > 0) {
        const dist = getDistance(unit.x, unit.y, d.data.x, d.data.y);
        if (dist < minDist) {
          minDist = dist;
          nearestTarget = d;
        }
      }
    });

    if (nearestTarget) {
      const targetUnit = (nearestTarget as UnitEntity).data;
      unit.targetId = targetUnit.id;

      if (minDist <= unit.attackRange) {
        entity.setState(new AttackState(targetUnit.id));
        entity.update(deltaTimeSec, context);
        return;
      }

      const moveDist = unit.speed * deltaTimeSec;
      const { dx, dy } = getDirection(unit.x, unit.y, targetUnit.x, targetUnit.y);

      unit.x += dx * moveDist;
      unit.y += dy * moveDist;
    } else {
      unit.targetId = undefined;
      unit.x -= unit.speed * deltaTimeSec;
    }
  }
}

export class AttackState implements UnitBehaviorState {
  name = 'Attack';
  private targetId: string;

  constructor(targetId: string) {
    this.targetId = targetId;
  }

  update(entity: UnitEntity, _deltaTimeSec: number, context?: SimulationContext): void {
    const unit = entity.data;
    if (!context) return;

    const targets = unit.team === 'defender' ? context.horde : context.defenders;
    const targetEntity = targets.find(t => t.data.id === this.targetId && t.data.hp > 0);

    if (!targetEntity) {
      unit.targetId = undefined;
      unit.isAttacking = false;
      this.returnToMovementState(entity);
      return;
    }

    const targetUnit = targetEntity.data;
    const dist = getDistance(unit.x, unit.y, targetUnit.x, targetUnit.y);

    if (dist > unit.attackRange + 15) {
      unit.targetId = undefined;
      unit.isAttacking = false;
      this.returnToMovementState(entity);
      return;
    }

    unit.isAttacking = true;

    if (context.now - unit.lastAttackTime >= unit.attackCooldown) {
      unit.lastAttackTime = context.now;
      unit.attackAnimTimer = 150;

      const rawDamage = isNaN(unit.damage) ? 0 : unit.damage;
      const targetArmor = isNaN(targetUnit.armor || 0) ? 0 : (targetUnit.armor || 0);
      const actualDamage = Math.max(1, rawDamage - targetArmor);

      context.onDealDamage(unit, targetUnit, actualDamage);
    }
  }

  private returnToMovementState(entity: UnitEntity) {
    if (entity.data.team === 'defender') {
      entity.setState(new DefenderEngageState());
    } else {
      entity.setState(new HordeMarchState());
    }
  }
}

export class IdleState implements UnitBehaviorState {
  name = 'Idle';
  update(): void {}
}

export class MoveState implements UnitBehaviorState {
  name = 'Move';
  update(entity: UnitEntity, deltaTimeSec: number): void {
    if (entity.data.team === 'horde') {
      entity.data.x -= deltaTimeSec * 50;
    }
  }
}

export class UnitEntity {
  public data: Unit;
  private state: UnitBehaviorState;

  constructor(data: Unit, initialState?: UnitBehaviorState) {
    this.data = data;
    if (data.homeX === undefined) this.data.homeX = data.x;
    if (data.homeY === undefined) this.data.homeY = data.y;

    if (initialState) {
      this.state = initialState;
    } else if (data.team === 'defender') {
      this.state = new DefenderHoldState();
    } else {
      this.state = new HordeMarchState();
    }
  }

  getStateName(): string {
    return this.state.name;
  }

  setState(newState: UnitBehaviorState) {
    this.state = newState;
  }

  update(deltaTimeMs: number, context?: SimulationContext) {
    const deltaTimeSec = deltaTimeMs / 1000;

    if (this.data.attackAnimTimer && this.data.attackAnimTimer > 0) {
      this.data.attackAnimTimer = Math.max(0, this.data.attackAnimTimer - deltaTimeMs);
      if (this.data.attackAnimTimer === 0) {
        this.data.isAttacking = false;
      }
    }

    this.state.update(this, deltaTimeSec, context);

    if (context) {
      this.clampPosition(context.canvasWidth, context.canvasHeight, context.zoneConfig);
    }
  }

  clampPosition(
    canvasWidth: number, 
    canvasHeight: number, 
    zoneConfig: BattlefieldZoneConfig = DEFAULT_BATTLEFIELD_ZONES
  ) {
    const marginY = 30;
    const marginX = 15;

    this.data.y = Math.max(marginY, Math.min(canvasHeight - marginY, this.data.y));

    if (this.data.team === 'defender') {
      // Clamped strictly to Player Area (default: 40% of canvas width)
      const defenderMaxX = canvasWidth * zoneConfig.playerAreaRatio;
      this.data.x = Math.max(marginX, Math.min(defenderMaxX, this.data.x));
    } else {
      // Horde area & neutral area (0 to canvasWidth)
      this.data.x = Math.max(marginX, Math.min(canvasWidth - marginX, this.data.x));
    }
  }
}
</file>

<file path="src/core/events/EventBus.ts">
import type { Unit } from '../../types/combat';

export interface GameEventPayloads {
  tick: { deltaTime: number };
  spawn: Unit;
  death: Unit;
  clear: void;
  pause: void;
  resume: void;
}

export type EventCallback<K extends keyof GameEventPayloads> = (
  ...args: GameEventPayloads[K] extends void ? [] : [GameEventPayloads[K]]
) => void;

export class EventBus {
  private listeners: { [K in keyof GameEventPayloads]?: EventCallback<K>[] } = {};

  on<K extends keyof GameEventPayloads>(event: K, callback: EventCallback<K>): void {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event]!.push(callback);
  }

  off<K extends keyof GameEventPayloads>(event: K, callback: EventCallback<K>): void {
    if (!this.listeners[event]) return;
    const array = this.listeners[event] as EventCallback<K>[];
    Object.assign(this.listeners, { [event]: array.filter(cb => cb !== callback) });
  }

  emit<K extends keyof GameEventPayloads>(
    event: K,
    ...args: GameEventPayloads[K] extends void ? [] : [GameEventPayloads[K]]
  ): void {
    if (!this.listeners[event]) return;
    this.listeners[event]!.forEach(cb => (cb as any)(...args));
  }

  clear(): void {
    this.listeners = {};
  }
}
</file>

<file path="src/core/factories/UnitFactory.ts">
import type { Unit, UnitTemplate, BattlefieldZoneConfig } from '../../types/combat';
import { DEFAULT_BATTLEFIELD_ZONES } from '../../types/combat';

// ─── Shared Deployment Grid Constants ────────────────────────────────────────
// These constants define the grid in both the Pre-Battle UI and the battle
// canvas. Using the same pixel cell size ensures a 1:1 spatial mapping so
// adjacent cells in the deployment grid are the same distance apart in combat.
export const DEPLOY_GRID_COLS = 5;
export const DEPLOY_GRID_ROWS = 8;
export const DEPLOY_CELL_PX = 60;    // px per grid cell (both axes, square cells)
export const DEPLOY_MARGIN_X = 30;   // px from left edge of spawn zone

/** Returns the top margin (px) that centres the deployment grid vertically on the canvas. */
export const getDeployMarginY = (canvasHeight: number): number =>
  Math.max(20, (canvasHeight - DEPLOY_GRID_ROWS * DEPLOY_CELL_PX) / 2);

export class UnitFactory {
  static createDefender(x: number, y: number, template?: Partial<Unit>): Unit {
    const unitType = (template as Partial<UnitTemplate>)?.type || 'common';
    const nameLower = (template?.name || '').toLowerCase();
    
    let defaultColor = '#22c55e';
    if (unitType === 'hero' || nameLower.includes('aric') || nameLower.includes('hero')) {
      defaultColor = '#f59e0b';
    } else if (unitType === 'elite') {
      defaultColor = '#a855f7';
    } else if (nameLower.includes('crossbow') || nameLower.includes('archer') || nameLower.includes('range')) {
      defaultColor = '#38bdf8';
    }

    return {
      id: template?.id || `defender-${Math.random().toString(36).substring(2, 9)}`,
      name: template?.name || 'Vanguard Spearman',
      hp: template?.hp ?? 120,
      maxHp: template?.maxHp ?? template?.hp ?? 120,
      damage: template?.damage ?? 15,
      armor: template?.armor ?? (unitType === 'hero' ? 8 : unitType === 'elite' ? 4 : 2),
      range: template?.range ?? (nameLower.includes('crossbow') ? 200 : 60),
      attackRange: template?.attackRange ?? template?.range ?? (nameLower.includes('crossbow') ? 200 : 60),
      attackCooldown: template?.attackCooldown ?? (nameLower.includes('crossbow') ? 1200 : 900),
      lastAttackTime: 0,
      speed: template?.speed ?? (unitType === 'hero' ? 100 : 85),
      team: 'defender',
      x,
      y,
      color: template?.color || defaultColor,
      gridPosition: template?.gridPosition,
      homeX: x,
      homeY: y,
    };
  }

  static createHorde(x: number, y: number, template?: Partial<Unit>): Unit {
    return {
      id: template?.id || `horde-${Math.random().toString(36).substring(2, 9)}`,
      name: template?.name || 'Orc Grunt',
      hp: template?.hp ?? 65,
      maxHp: template?.maxHp ?? 65,
      damage: template?.damage ?? 9,
      armor: template?.armor ?? 1,
      range: template?.range ?? 35,
      attackRange: template?.attackRange ?? template?.range ?? 35,
      attackCooldown: template?.attackCooldown ?? 900,
      lastAttackTime: 0,
      speed: template?.speed ?? 70,
      team: 'horde',
      x,
      y,
      color: template?.color || '#ef4444',
      homeX: x,
      homeY: y,
    };
  }

  static fromTemplate(
    template: UnitTemplate, 
    canvasWidth: number, 
    canvasHeight: number,
    zoneConfig: BattlefieldZoneConfig = DEFAULT_BATTLEFIELD_ZONES
  ): Unit {
    // Player Spawn Zone (default: 0% to 30% of canvas width)
    const spawnZoneWidth = canvasWidth * zoneConfig.playerSpawnRatio;

    let x: number;
    let y: number;

    if (template.gridPosition) {
      // ── 1:1 fixed-cell-size placement ──────────────────────────────────────
      // Each grid cell is exactly DEPLOY_CELL_PX × DEPLOY_CELL_PX pixels.
      // getDeployMarginY centres the grid vertically so the battle placement
      // matches whatever is drawn in the canvas grid overlay.
      const marginY = getDeployMarginY(canvasHeight);
      x = DEPLOY_MARGIN_X + (template.gridPosition.x + 0.5) * DEPLOY_CELL_PX;
      y = marginY + (template.gridPosition.y + 0.5) * DEPLOY_CELL_PX;

      // Safety clamp: keep within spawn zone / canvas bounds
      x = Math.min(x, spawnZoneWidth - 20);
      y = Math.max(20, Math.min(y, canvasHeight - 20));
    } else {
      // Fallback: centre of spawn zone
      x = spawnZoneWidth * 0.5;
      y = canvasHeight * 0.5;
    }

    const nameLower = (template.name || '').toLowerCase();
    let defaultColor = '#22c55e';
    if (template.type === 'hero' || nameLower.includes('aric')) {
      defaultColor = '#f59e0b';
    } else if (template.type === 'elite') {
      defaultColor = '#a855f7';
    } else if (nameLower.includes('crossbow') || nameLower.includes('archer')) {
      defaultColor = '#38bdf8';
    }

    return UnitFactory.createDefender(x, y, {
      id: template.id,
      name: template.name,
      hp: template.hp,
      maxHp: template.maxHp || template.hp,
      damage: template.damage,
      range: template.range,
      attackRange: template.range,
      color: defaultColor,
      gridPosition: template.gridPosition,
    });
  }
}
</file>

