import React from 'react';
import type { GameState } from '../../types/game';
import type { Unit } from '../../types/combat';
import { ArrowLeft, Pause, Play, FastForward, RefreshCw, Skull, Shield, Info, X, ChevronUp, ChevronDown, Swords, Flag } from 'lucide-react';

interface Props {
  hudStats: {
    fps: number;
    defendersCount: number;
    hordeCount: number;
    phase: string;
  };
  selectedUnit: { unit: Unit; stateName: string } | null;
  setSelectedUnit: (val: { unit: Unit; stateName: string } | null) => void;
  isPaused: boolean;
  togglePause: () => void;
  gameSpeed?: number;
  setGameSpeed?: (speed: number) => void;
  onSurrenderBattle?: () => void;
  enemyMenuOpen: boolean;
  setEnemyMenuOpen: (val: boolean | ((prev: boolean) => boolean)) => void;
  ENEMY_CATALOGUE: readonly { label: string; icon: string; color: string; stats: Partial<Unit>; }[];
  spawnEnemies: (stats: Partial<Unit>, count: number) => void;
  initBattlefield: () => void;
  onBackToMap?: () => void;
  onNavigate?: (view: GameState) => void;
  isSandboxMode?: boolean;
  onSurrenderCity?: () => void;
  onVictoryComplete?: () => void;
}

const QuadrupleArrowIcon: React.FC<{ className?: string }> = ({ className = "w-3.5 h-3" }) => (
  <svg viewBox="0 0 26 24" fill="currentColor" className={className}>
    <polygon points="2,4 9,12 2,20" />
    <polygon points="8,4 15,12 8,20" />
    <polygon points="14,4 21,12 14,20" />
    <polygon points="20,4 25,12 20,20" />
  </svg>
);

export const BattleCanvasOverlay: React.FC<Props> = ({
  hudStats,
  selectedUnit,
  setSelectedUnit,
  isPaused,
  togglePause,
  gameSpeed = 1,
  setGameSpeed,
  onSurrenderBattle,
  enemyMenuOpen,
  setEnemyMenuOpen,
  ENEMY_CATALOGUE,
  spawnEnemies,
  initBattlefield,
  onBackToMap,
  onNavigate,
  isSandboxMode = false,
  onSurrenderCity,
  onVictoryComplete,
}) => {

  return (
    <div className="absolute inset-0 z-10 pointer-events-none flex flex-col justify-between p-6">
      {/* Top Control Bar & Debug HUD */}
      <div className="flex justify-between items-start pointer-events-auto">
        {/* Left Action Buttons */}
        <div className="flex gap-3 items-center">
          {onBackToMap ? (
            <button
              onClick={onBackToMap}
              className="px-4 py-2.5 rounded-xl flex items-center justify-center gap-2 bg-slate-900/80 hover:bg-slate-800 border border-slate-700 text-amber-400 font-bold text-sm shadow-xl backdrop-blur-md transition-all"
            >
              <ArrowLeft className="w-4 h-4" /> {isSandboxMode ? 'Back to Sandbox' : 'Return to Pre-Battle Planning'}
            </button>
          ) : onNavigate ? (
            <button
              onClick={() => onNavigate('battle')}
              className="px-4 py-2.5 rounded-xl flex items-center justify-center gap-2 bg-slate-900/80 hover:bg-slate-800 border border-slate-700 text-amber-400 font-bold text-sm shadow-xl backdrop-blur-md transition-all"
            >
              <ArrowLeft className="w-4 h-4" /> {isSandboxMode ? 'Back to Sandbox' : 'Return to Pre-Battle Planning'}
            </button>
          ) : null}

          {/* Integrated Segmented Speed Control (0x / 0.5x / 1x / 2x / 4x) */}
          <div className="flex bg-slate-950/90 border border-slate-800 p-1 rounded-xl shadow-xl backdrop-blur-md items-center gap-1 font-mono text-xs font-bold">
            {[0, 0.5, 1, 2, 4].map((speed) => {
              const isActive = speed === 0 ? isPaused : (!isPaused && gameSpeed === speed);
              return (
                <button
                  key={speed}
                  onClick={() => {
                    if (speed === 0) {
                      if (!isPaused) togglePause();
                    } else {
                      if (isPaused) togglePause();
                      setGameSpeed?.(speed);
                    }
                  }}
                  className={`px-3 py-1.5 rounded-lg transition-all flex items-center gap-1 ${
                    isActive
                      ? 'bg-amber-500 text-slate-950 shadow-md font-extrabold scale-[1.03]'
                      : 'text-slate-400 hover:text-white hover:bg-slate-800/80'
                  }`}
                  title={speed === 0 ? 'Pause simulation (0x speed)' : `Set speed to ${speed}x`}
                >
                  {speed === 0 && <Pause className="w-3 h-3 fill-current" />}
                  {speed === 0.5 && <Play className="w-3 h-3 fill-current opacity-60" />}
                  {speed === 1 && <Play className="w-3 h-3 fill-current" />}
                  {speed === 2 && <FastForward className="w-3 h-3 fill-current" />}
                  {speed === 4 && <QuadrupleArrowIcon className="w-3.5 h-3 fill-current" />}
                  {speed}x
                </button>
              );
            })}
          </div>

          {onSurrenderBattle && hudStats.phase !== 'DEFEAT' && hudStats.phase !== 'SURRENDERED' && hudStats.phase !== 'VICTORY' && (
            <button
              onClick={onSurrenderBattle}
              className="px-4 py-2 rounded-xl flex items-center justify-center gap-2 bg-red-950/80 hover:bg-red-900 border border-red-800 text-red-300 font-bold text-sm shadow-xl backdrop-blur-md transition-all hover:scale-[1.02]"
              title="Surrender battle immediately"
            >
              <Flag className="w-4 h-4 text-red-400" /> Surrender
            </button>
          )}
        </div>

        {/* Right Compact Stats Overlay */}
        <div className="bg-slate-950/90 backdrop-blur-md border border-slate-800/80 px-3 py-1.5 rounded-lg flex gap-3 text-[11px] font-mono shadow-xl items-center border-l-2 border-l-amber-500">
          <div className="flex items-center gap-1.5">
            <span className="opacity-50 text-[9px] uppercase tracking-wider">FPS</span>
            <span className="text-amber-400 font-bold text-xs">{hudStats.fps}</span>
          </div>
          <div className="w-px h-3.5 bg-slate-800" />
          <div className="flex items-center gap-1.5">
            <span className="opacity-50 text-[9px] uppercase tracking-wider">Def</span>
            <span className="text-emerald-400 font-bold text-xs">{hudStats.defendersCount}</span>
          </div>
          <div className="w-px h-3.5 bg-slate-800" />
          <div className="flex items-center gap-1.5">
            <span className="opacity-50 text-[9px] uppercase tracking-wider">Horde</span>
            <span className="text-red-400 font-bold text-xs">{hudStats.hordeCount}</span>
          </div>
          <div className="w-px h-3.5 bg-slate-800" />
          <div className="flex items-center gap-1.5">
            <span className="opacity-50 text-[9px] uppercase tracking-wider">Phase</span>
            <span className={`font-bold text-[10px] uppercase ${
              hudStats.phase === 'VICTORY' ? 'text-emerald-400' :
              hudStats.phase === 'DEFEAT' || hudStats.phase === 'SURRENDERED' ? 'text-red-400' :
              hudStats.phase === 'ENGAGING_ENEMY' ? 'text-amber-400' : 'text-cyan-400'
            }`}>
              {hudStats.phase}
            </span>
          </div>
        </div>
      </div>

      {/* Selected Unit Inspection Card Overlay */}
      {selectedUnit && (
        <div className="absolute top-20 left-6 z-40 pointer-events-auto bg-slate-950/90 backdrop-blur-md border border-cyan-500/50 p-4 rounded-xl shadow-2xl w-64 text-xs font-sans">
          <div className="flex justify-between items-center mb-2 pb-2 border-b border-slate-800">
            <div className="flex items-center gap-2">
              <Info className="w-4 h-4 text-cyan-400" />
              <span className="font-bold text-sm text-white">{selectedUnit.unit.name}</span>
            </div>
            <button onClick={() => setSelectedUnit(null)} className="text-slate-400 hover:text-white">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="space-y-1.5 font-mono text-slate-300">
            <div className="flex justify-between">
              <span className="opacity-60">Team:</span>
              <span className={`font-bold uppercase ${selectedUnit.unit.team === 'defender' ? 'text-emerald-400' : 'text-red-400'}`}>
                {selectedUnit.unit.team}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="opacity-60">HP:</span>
              <span className="text-emerald-400 font-bold">{selectedUnit.unit.hp} / {selectedUnit.unit.maxHp}</span>
            </div>
            <div className="flex justify-between">
              <span className="opacity-60">Damage:</span>
              <span className="text-amber-400 font-bold">{selectedUnit.unit.damage}</span>
            </div>
            <div className="flex justify-between">
              <span className="opacity-60">Armor:</span>
              <span className="text-cyan-400 font-bold">{selectedUnit.unit.armor || 0}</span>
            </div>
            <div className="flex justify-between">
              <span className="opacity-60">Range:</span>
              <span className="text-slate-200">{selectedUnit.unit.range}px</span>
            </div>
            <div className="flex justify-between">
              <span className="opacity-60">AI State:</span>
              <span className="text-purple-400 font-bold">{selectedUnit.stateName}</span>
            </div>
          </div>
        </div>
      )}

      {/* Bottom Interactive Control Panel (Sandbox Mode Only) */}
      {isSandboxMode && (
        <div className="pointer-events-auto flex flex-col items-center gap-2 pb-4">
          {/* Enemy Spawn Menu */}
          {enemyMenuOpen && (
            <div className="bg-slate-950/95 backdrop-blur-md border border-red-900/60 rounded-2xl shadow-2xl p-4 w-[660px] max-w-[95vw]">
              <div className="flex items-center gap-2 mb-3 pb-2 border-b border-slate-800">
                <Skull className="w-4 h-4 text-red-400" />
                <span className="text-xs font-black uppercase tracking-widest text-red-400">Spawn Enemies</span>
                <span className="text-[10px] text-slate-500 ml-1">— unlimited, spawns from the right</span>
              </div>

              <div className="grid grid-cols-2 gap-2">
                {ENEMY_CATALOGUE.map(entry => (
                  <div
                    key={entry.label}
                    className="flex items-center gap-3 bg-slate-900/80 border border-slate-800 hover:border-slate-700 rounded-xl px-3 py-2 transition-colors"
                  >
                    <span className="text-lg leading-none select-none">{entry.icon}</span>
                    <div className="flex-1 min-w-0">
                      <p className="text-xs font-bold text-white truncate">{entry.label}</p>
                      <p className="text-[10px] text-slate-500 font-mono">
                        HP {entry.stats.hp} · DMG {entry.stats.damage} · SPD {entry.stats.speed}
                        {(entry.stats.armor ?? 0) > 0 ? ` · ARM ${entry.stats.armor}` : ''}
                      </p>
                    </div>
                    <div className="flex gap-1 shrink-0">
                      {([1, 5, 10] as const).map(n => (
                        <button
                          key={n}
                          onClick={() => spawnEnemies(entry.stats, n)}
                          className="px-2 py-1 rounded-lg text-[10px] font-black border border-red-800/60 hover:bg-red-900/30 text-red-300 transition-colors"
                        >
                          +{n}
                        </button>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Persistent Action Bar */}
          <div className="bg-slate-950/90 backdrop-blur-md border border-slate-800 p-3 rounded-2xl flex gap-3 shadow-2xl items-center">
            <button
              onClick={initBattlefield}
              className="px-4 py-2.5 rounded-xl border border-amber-500/40 hover:bg-amber-500/10 text-amber-300 text-xs font-bold flex gap-2 items-center transition-colors"
            >
              <RefreshCw className="w-4 h-4" /> Reset Formation
            </button>
            <div className="w-px h-6 bg-slate-800" />
            <button
              onClick={() => setEnemyMenuOpen(o => !o)}
              className={`px-4 py-2.5 rounded-xl border text-xs font-bold flex gap-2 items-center transition-colors ${
                enemyMenuOpen
                  ? 'border-red-500 bg-red-900/30 text-red-300'
                  : 'border-red-500/40 hover:bg-red-500/10 text-red-400'
              }`}
            >
              <Swords className="w-4 h-4" />
              Spawn Enemies
              {enemyMenuOpen
                ? <ChevronDown className="w-3 h-3" />
                : <ChevronUp className="w-3 h-3" />
              }
            </button>
          </div>
        </div>
      )}

      {/* Victory / Defeat Overlay Banners */}
      {hudStats.phase === 'VICTORY' && (
        <div className="absolute inset-0 z-50 pointer-events-auto flex items-center justify-center bg-black/70 backdrop-blur-sm animate-fade-in">
          <div className="bg-slate-900 border-2 border-emerald-500/80 p-8 rounded-2xl max-w-md w-full text-center shadow-2xl">
            <Shield className="w-16 h-16 text-emerald-400 mx-auto mb-4 animate-bounce" />
            <h2 className="text-3xl font-extrabold text-emerald-400 uppercase tracking-widest mb-2">Victory!</h2>
            <p className="text-slate-300 text-sm mb-6">The defensive line held strong against the horde infestation.</p>
            <button
              onClick={onVictoryComplete || onBackToMap || (() => onNavigate?.('battle'))}
              className="w-full py-3.5 bg-emerald-600 hover:bg-emerald-500 text-white font-black uppercase tracking-wider rounded-xl shadow-lg transition-all"
            >
              {isSandboxMode ? 'Return to Sandbox' : 'Continue Campaign'}
            </button>
          </div>
        </div>
      )}

      {(hudStats.phase === 'DEFEAT' || hudStats.phase === 'SURRENDERED') && (
        <div className="absolute inset-0 z-50 pointer-events-auto flex items-center justify-center bg-black/80 backdrop-blur-sm animate-fade-in">
          <div className="bg-slate-900 border-2 border-red-500/80 p-8 rounded-2xl max-w-md w-full text-center shadow-2xl">
            {hudStats.phase === 'SURRENDERED' ? (
              <Flag className="w-16 h-16 text-red-500 mx-auto mb-4 animate-bounce" />
            ) : (
              <Skull className="w-16 h-16 text-red-500 mx-auto mb-4 animate-pulse" />
            )}
            <h2 className="text-3xl font-extrabold text-red-500 uppercase tracking-widest mb-2">
              {hudStats.phase === 'SURRENDERED' ? 'Surrender!' : 'Defeat!'}
            </h2>
            <p className="text-slate-300 text-sm mb-6">
              {hudStats.phase === 'SURRENDERED'
                ? 'You chose to surrender this engagement.'
                : 'The defenders were overwhelmed. The territory has fallen.'}
            </p>
            <div className="flex flex-col gap-3">
              <div className="flex gap-3">
                <button
                  onClick={initBattlefield}
                  className="flex-1 py-3 bg-slate-800 hover:bg-slate-700 border border-slate-600 text-slate-200 font-bold rounded-xl text-sm transition-all"
                >
                  Retry Battle
                </button>
                <button
                  onClick={onBackToMap || (() => onNavigate?.('battle'))}
                  className="flex-1 py-3 bg-slate-800 hover:bg-slate-700 border border-slate-600 text-slate-300 font-bold rounded-xl text-sm transition-all"
                >
                  {isSandboxMode ? 'Retreat' : 'Pre-Battle Planning'}
                </button>
              </div>
              {!isSandboxMode && (
                <button
                  onClick={onSurrenderCity || onBackToMap}
                  className="w-full py-3 bg-red-700 hover:bg-red-600 text-white font-black uppercase tracking-wider rounded-xl text-xs shadow-lg transition-all"
                >
                  Give Up City (+250g Salvage)
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
</file>

<file path="src/features/combat/FormationGrid.tsx">
import React, { useState, useRef } from 'react';
import { Sparkles, X, ArrowLeft, Move, ZoomIn, ZoomOut } from 'lucide-react';
import {
  DEPLOY_GRID_COLS,
  DEPLOY_GRID_ROWS,
  DEPLOY_CELL_PX,
} from '../../core/factories/UnitFactory';

import type { UnitTemplate } from '../../types/combat';

interface Props {
  assignedUnits: UnitTemplate[];
  isAnySelected: boolean;
  handleCellClick: (x: number, y: number) => void;
}

const GRID_COLS = DEPLOY_GRID_COLS;
const GRID_ROWS = DEPLOY_GRID_ROWS;
const CELL_SIZE = DEPLOY_CELL_PX;

export const FormationGrid: React.FC<Props> = ({ assignedUnits, isAnySelected, handleCellClick }) => {
  // Pan & Zoom State
  const [panOffset, setPanOffset] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [zoomScale, setZoomScale] = useState<number>(1.0);
  const MIN_ZOOM = 0.6;
  const MAX_ZOOM = 1.8;

  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const panStartRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const didDragRef = useRef(false);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return;
    setIsDragging(true);
    didDragRef.current = false;
    dragStartRef.current = { x: e.clientX, y: e.clientY };
    panStartRef.current = { ...panOffset };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    const dx = e.clientX - dragStartRef.current.x;
    const dy = e.clientY - dragStartRef.current.y;

    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
      didDragRef.current = true;
    }

    setPanOffset({
      x: panStartRef.current.x + dx,
      y: panStartRef.current.y + dy,
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleWheel = (e: React.WheelEvent) => {
    const delta = e.deltaY < 0 ? 0.1 : -0.1;
    setZoomScale(prev => Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, parseFloat((prev + delta).toFixed(2)))));
  };

  const handleZoomIn = (e: React.MouseEvent) => {
    e.stopPropagation();
    setZoomScale(prev => Math.min(MAX_ZOOM, parseFloat((prev + 0.15).toFixed(2))));
  };

  const handleZoomOut = (e: React.MouseEvent) => {
    e.stopPropagation();
    setZoomScale(prev => Math.max(MIN_ZOOM, parseFloat((prev - 0.15).toFixed(2))));
  };

  const handleResetView = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPanOffset({ x: 0, y: 0 });
    setZoomScale(1.0);
  };

  const onCellClickWrapper = (x: number, y: number) => {
    if (!didDragRef.current) {
      handleCellClick(x, y);
    }
  };

  return (
    <div
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      className={`flex-1 relative flex flex-col items-center justify-center bg-slate-950 overflow-hidden select-none p-6 ${
        isDragging ? 'cursor-grabbing' : 'cursor-grab'
      }`}
    >
      {/* Pan & Zoom Controls */}
      <div className="absolute top-4 left-4 z-10 flex items-center gap-2 bg-slate-900/85 backdrop-blur border border-slate-800 px-3 py-1.5 rounded-lg text-xs text-slate-400 font-sans shadow-md">
        <span className="flex items-center gap-1 text-slate-300 font-semibold mr-2">
          <Move className="w-3.5 h-3.5 text-cyan-400" /> Scroll / Drag Grid
        </span>
        <div className="flex items-center gap-1 border-l border-slate-800 pl-2">
          <button
            onClick={handleZoomOut}
            disabled={zoomScale <= MIN_ZOOM}
            className="p-1 hover:bg-slate-800 text-slate-300 disabled:opacity-30 rounded transition-colors"
            title="Zoom Out"
          >
            <ZoomOut className="w-3.5 h-3.5" />
          </button>
          <span className="text-[11px] font-mono font-bold text-amber-400 w-10 text-center">
            {Math.round(zoomScale * 100)}%
          </span>
          <button
            onClick={handleZoomIn}
            disabled={zoomScale >= MAX_ZOOM}
            className="p-1 hover:bg-slate-800 text-slate-300 disabled:opacity-30 rounded transition-colors"
            title="Zoom In"
          >
            <ZoomIn className="w-3.5 h-3.5" />
          </button>
        </div>
        {(panOffset.x !== 0 || panOffset.y !== 0 || zoomScale !== 1.0) && (
          <button
            onClick={handleResetView}
            className="ml-1 px-2 py-0.5 bg-slate-800 hover:bg-slate-700 text-amber-400 rounded text-[11px] font-bold transition-colors"
          >
            Reset
          </button>
        )}
      </div>

      {/* Draggable & Scalable Grid Container */}
      <div
        style={{
          transform: `translate(${panOffset.x}px, ${panOffset.y}px) scale(${zoomScale})`,
          transformOrigin: 'center center',
          transition: isDragging ? 'none' : 'transform 0.1s ease-out',
        }}
        className="flex flex-col items-center justify-center"
      >
        <div className="text-[10px] md:text-xs uppercase tracking-widest text-slate-500 mb-3 font-bold flex justify-between w-full" style={{ maxWidth: GRID_COLS * CELL_SIZE + 120 }}>
          <span>← Player Defence Zone ({GRID_COLS}×{GRID_ROWS})</span>
          <span className="text-amber-400">★ Gold = Choke Point (+20% Def)</span>
        </div>

        <div className="flex items-center gap-4">
          <div 
            className="grid bg-slate-950 p-3 rounded-xl border border-slate-800 shadow-2xl"
            style={{
              gridTemplateColumns: `repeat(${GRID_COLS}, ${CELL_SIZE}px)`,
              gap: '6px',
            }}
          >
            {Array.from({ length: GRID_ROWS }).map((_, y) => 
              Array.from({ length: GRID_COLS }).map((_, x) => {
                const isChokePoint = y === 3 || y === 4;
                const occupant = assignedUnits.find(u => u.gridPosition?.x === x && u.gridPosition?.y === y);

                return (
                  <button
                    key={`${x}-${y}`}
                    onClick={() => onCellClickWrapper(x, y)}
                    style={{ width: CELL_SIZE, height: CELL_SIZE }}
                    className={`aspect-square rounded-lg border-2 flex flex-col items-center justify-center relative transition-all shrink-0 group ${
                      occupant 
                        ? 'bg-slate-800 border-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.2)]' 
                        : isChokePoint
                          ? 'border-amber-400/60 bg-amber-950/20 hover:bg-amber-900/30'
                          : 'border-slate-800 bg-slate-900/80 hover:border-slate-600'
                    } ${isAnySelected && !occupant ? 'hover:border-cyan-400 hover:bg-cyan-950/30 animate-pulse' : ''}`}
                  >
                    {isChokePoint && !occupant && (
                      <Sparkles className="w-3 h-3 text-amber-400/40 absolute top-1 right-1" />
                    )}

                    {occupant ? (
                      <div className="flex flex-col items-center justify-between p-1 text-center w-full h-full relative z-0">
                        <div className="w-full h-1.5 bg-slate-950 border border-slate-700 rounded-full overflow-hidden shrink-0 mt-0.5">
                          <div 
                            className="h-full bg-emerald-500 rounded-full transition-all"
                            style={{ width: `${Math.max(0, Math.min(100, (occupant.hp / (occupant.maxHp || occupant.hp)) * 100))}%` }}
                          />
                        </div>
                        <div className={`w-6 h-6 rounded-full border-2 shrink-0 shadow-md flex items-center justify-center ${
                          occupant.type === 'hero' 
                            ? 'bg-amber-500 border-amber-300 shadow-[0_0_8px_rgba(245,158,11,0.5)]' 
                            : occupant.type === 'elite'
                            ? 'bg-purple-600 border-purple-300 shadow-[0_0_8px_rgba(147,51,234,0.5)]'
                            : 'bg-blue-600 border-cyan-300 shadow-[0_0_8px_rgba(6,182,212,0.4)]'
                        }`} />
                        <span className="text-[8px] font-bold text-slate-200 truncate max-w-full leading-tight text-center mb-0.5">
                          {occupant.name}
                        </span>
                        <div className="absolute inset-0 bg-red-900/80 opacity-0 group-hover:opacity-100 flex items-center justify-center rounded-lg transition-opacity z-10">
                          <X className="w-4 h-4 text-white" />
                        </div>
                      </div>
                    ) : (
                      <span className="text-[8px] text-slate-700 font-mono">
                        {x},{y}
                      </span>
                    )}
                  </button>
                );
              })
            )}
          </div>

          <div className="flex flex-col items-center justify-center bg-red-950/40 border border-red-800/80 p-3 rounded-xl text-red-400 shrink-0 shadow-lg select-none">
            <div className="flex items-center gap-1 animate-pulse">
              <ArrowLeft className="w-6 h-6 text-red-500 stroke-[3]" />
              <span className="text-xs font-black tracking-widest text-red-400 hidden sm:inline">
                ATTACK
              </span>
            </div>
            <span className="text-[10px] font-bold uppercase tracking-wider text-red-300/80 mt-1 text-center leading-tight">
              Enemy Wave<br />Direction
            </span>
          </div>
        </div>

        <p className="text-[10px] text-slate-600 mt-4 text-center">
          Each grid cell = {CELL_SIZE}px in battle · Formation shape is preserved exactly on launch
        </p>
      </div>
    </div>
  );
};
</file>

<file path="src/features/combat/UnitRosterList.tsx">
import React from 'react';
import { Layers, Infinity, UserCheck } from 'lucide-react';

import type { UnitTemplate } from '../../types/combat';

export type StackEntry = {
  name: string;
  type: string;
  hp: number;
  damage: number;
  units: UnitTemplate[];
  infinite: boolean;
  template?: UnitTemplate;
};

interface Props {
  isSandboxMode: boolean;
  unassignedUnits: UnitTemplate[];
  assignedUnits: UnitTemplate[];
  displayStacks: StackEntry[];
  selectionLabel: string | null;
  isSandboxSelection: boolean;
  sandboxSelectedName: string | null;
  selectedUnit: UnitTemplate | undefined;
  handleStackClick: (stack: StackEntry) => void;
  handleClearAll: () => void;
}

export const UnitRosterList: React.FC<Props> = ({
  isSandboxMode,
  unassignedUnits,
  assignedUnits,
  displayStacks,
  selectionLabel,
  isSandboxSelection,
  sandboxSelectedName,
  selectedUnit,
  handleStackClick,
  handleClearAll
}) => {
  return (
    <div className="w-[576px] flex-shrink-0 flex flex-col bg-slate-900 border-r border-slate-800 overflow-hidden">
      <div className="flex-shrink-0 flex justify-between items-center px-4 py-3 border-b border-slate-800">
        <div className="flex items-center gap-2">
          <Layers className="w-4 h-4 text-amber-400" />
          <h3 className="text-xs font-bold uppercase tracking-wider text-amber-400">
            Unit Bench
          </h3>
          {isSandboxMode ? (
            <span className="text-[10px] text-cyan-400 font-mono flex items-center gap-1">
              (<Infinity className="w-3 h-3 inline" /> non-hero)
            </span>
          ) : (
            <span className="text-[10px] text-slate-500 font-mono">
              ({unassignedUnits.length} ready)
            </span>
          )}
        </div>
        {assignedUnits.length > 0 && (
          <button 
            onClick={handleClearAll}
            className="text-[10px] text-red-400 hover:text-red-300 font-bold uppercase tracking-wider"
          >
            Clear ({assignedUnits.length})
          </button>
        )}
      </div>

      {selectionLabel && (
        <div className="flex-shrink-0 mx-3 mt-3 px-3 py-2 bg-cyan-950 border border-cyan-700 rounded-lg">
          <p className="text-[11px] text-cyan-300 font-bold flex items-center gap-1">
            <UserCheck className="w-3 h-3" />
            Deploying: <span className="text-white">{selectionLabel}</span>
            {isSandboxSelection && <span className="text-cyan-500 ml-1">(∞)</span>}
          </p>
          <p className="text-[10px] text-cyan-500 mt-0.5">Click a grid cell to place · Click again to deselect</p>
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-3">
        <div className="grid grid-cols-2 gap-2">
        {displayStacks.length === 0 ? (
          <div className="col-span-2 text-slate-500 text-xs italic py-4 text-center">
            {assignedUnits.length === 0 
              ? "No defenders allocated yet. Go to Empire Management to assign troops."
              : "All defenders deployed!"
            }
          </div>
        ) : (
          displayStacks.map(stack => {
            const isSelectedStack = isSandboxSelection
              ? sandboxSelectedName === stack.name
              : selectedUnit && selectedUnit.name === stack.name;
            return (
              <button
                key={stack.name}
                onClick={() => handleStackClick(stack)}
                className={`w-full flex flex-col items-start p-3 rounded-lg border-2 transition-all text-left relative ${
                  isSelectedStack 
                    ? 'border-cyan-400 bg-cyan-950/60 shadow-[0_0_15px_rgba(6,182,212,0.3)] scale-[1.02]' 
                    : 'border-slate-700 bg-slate-950 hover:border-slate-500 hover:bg-slate-900/80'
                }`}
              >
                <div className={`absolute top-2 right-2 px-2 py-0.5 font-black text-[10px] rounded-full shadow-md flex items-center gap-0.5 ${
                  stack.infinite
                    ? 'bg-cyan-600 text-white'
                    : 'bg-amber-500 text-black'
                }`}>
                  {stack.infinite ? <Infinity className="w-3 h-3" /> : `×${stack.units.length}`}
                </div>

                <div className="flex items-center gap-2 pr-8 w-full">
                  <div className={`w-3 h-3 rounded-full flex-shrink-0 ${
                    stack.type === 'hero' 
                      ? 'bg-amber-400 shadow-[0_0_6px_rgba(245,158,11,0.6)]' 
                      : stack.type === 'elite'
                      ? 'bg-purple-500 shadow-[0_0_6px_rgba(147,51,234,0.5)]'
                      : 'bg-blue-400 shadow-[0_0_6px_rgba(96,165,250,0.4)]'
                  }`} />
                  <span className="font-bold text-white text-sm truncate">{stack.name}</span>
                </div>
                <span className="text-[10px] text-slate-400 uppercase mt-0.5 ml-5">
                  {stack.type}{stack.infinite ? ' · Unlimited' : ''}
                </span>
                
                <div className="text-[11px] text-slate-400 mt-2 font-mono flex justify-between w-full">
                  <span>HP: {stack.hp}</span>
                  <span>DMG: {stack.damage}</span>
                </div>

                {isSelectedStack && (
                  <div className="mt-2 text-[10px] text-cyan-300 font-bold flex items-center gap-1">
                    <UserCheck className="w-3 h-3" /> Ready to Place
                  </div>
                )}
              </button>
            );
          })
        )}
        </div>
      </div>

      {assignedUnits.length > 0 && (
        <div className="flex-shrink-0 px-4 py-3 border-t border-slate-800 bg-slate-950/60">
          <p className="text-[10px] text-slate-500 uppercase tracking-wider font-bold">Deployed</p>
          <p className="text-sm font-bold text-emerald-400">{assignedUnits.length} units on grid</p>
        </div>
      )}
    </div>
  );
};
</file>

