                onOpenUnitManager={handleOpenUnitManager}
              />
            </div>
          </div>
        )}

        {/* ── View 2: Army Logistics (Full Screen 2-Column Manager) ── */}
        {viewMode === 'logistics' && (
          <div className="flex-1 overflow-hidden bg-slate-900">
            <UnitLogisticsPanel
              territories={territories}
              globalUnitPool={globalUnitPool}
