        <button
          onClick={() => setPanelTab('city')}
          className="flex-1 py-1.5 rounded-lg text-xs font-bold text-amber-300 bg-slate-800 border border-slate-700 transition-colors flex items-center justify-center gap-1.5 shadow"
        >
