        ) : (
          <div className="text-center text-red-500 font-bold py-3 uppercase tracking-widest text-sm bg-red-950/30 border border-red-900/40 rounded-lg">
            Territory Scorched
          </div>
        )}
      </div>
    </div>
  );
};

